-- Àrees de destreses del Quadern C2 de la JQCV (2. Objectius per àrees), amb el mateix format que les del
-- C1 (20261015110000). Les estructures lingüístiques es treballen en els continguts de llengua del C2.
-- Els àudios es generen amb el TTS (backend/scripts/generate-practice-audio.ts) a
-- /audio/practice/<type>-c2-<posició>.wav. Tornar a aplicar el fitxer no duplica res.

DO $do$
DECLARE
  catalog jsonb := $data$[
  {"id": "3a1ea36f-05a7-5c8e-ad0d-dd1ae0625348", "category": "comprensio_escrita", "type": "c2_ce_actituds", "sort_order": 1, "title": "Actituds i opinions de l'autor", "name": "Informes, recomanacions i textos acadèmics i professionals", "content": "Comprén textos de la vida social, professional i acadèmica i hi identifica els detalls subtils, les actituds i les opinions de qui escriu, tant explícites com implícites (2.1).", "icon": "🧐", "color": "#D7CCC8", "blocks": [{"passage": {"media": "text", "title": "Informe de revisió d'un manuscrit científic", "lines": [{"text": "Informe del revisor 2 sobre el manuscrit «Jornada compacta i rendiment en l'educació primària valenciana»"}, {"text": "Agraïsc a l'equip editorial la confiança i he llegit el manuscrit amb l'atenció que mereix un treball que, d'entrada, aborda una qüestió rellevant. Cal reconéixer l'esforç de recollida de dades: quaranta-dos centres, tres cursos acadèmics i prop de dos-centes entrevistes amb docents. Les autores mostren, a més, una familiaritat envejable amb la bibliografia anglosaxona, que citen amb una generositat poc habitual."}, {"text": "Dit això, em veig obligat a formular certes reserves sobre l'abast de les conclusions. El resum afirma que la jornada compacta «millora» el rendiment; en el cos de l'article, però, la correlació es limita a dues de les sis àrees avaluades, i la diferència mitjana (tres dècimes sobre deu) queda dins del marge d'error que les mateixes autores reconeixen en una nota a peu de pàgina. Hom podria pensar que una nota a peu de pàgina és un lloc ben discret per a una limitació tan central."}, {"text": "Pel que fa a la metodologia, la mostra no és aleatòria: els centres que van accedir a participar són, amb tota probabilitat, els més motivats, i els més motivats tendixen a obtindre millors resultats amb qualsevol horari. Sorprén que la discussió no se'n faça càrrec, sobretot quan el mateix text, unes pàgines abans, es declara «conscient dels biaixos de selecció»."}, {"text": "Les entrevistes amb els docents constituïxen, al meu parer, el material més valuós i, alhora, el menys explotat. Se'n reproduïxen només set fragments, tots favorables a la jornada compacta, i l'article no explica amb quin criteri s'han triat. No dubte de la bona fe de les autores; però un lector atent es demanarà si les altres cent noranta-tres entrevistes diuen el mateix, o si algú va decidir que no calia reproduir-les."}, {"text": "En les taules 3 i 4, les desviacions típiques no s'ofereixen per a tots els grups, i la figura 2 trunca l'eix vertical, de manera que una diferència menuda pareix un abisme. Estic segur que és una qüestió de maquetació i no d'intenció; en tot cas, convé corregir-ho abans que res, perquè és el que el lector veu primer."}, {"text": "La redacció és àgil, potser massa. Hi ha frases que busquen l'efecte retòric («el rellotge escolar no és neutre») més que la demostració, i l'epígraf final, «Cap a un nou paradigma», promet més del que el text lliura. Agrairia que se suprimira."}, {"text": "Recomane, doncs, una revisió major. Si les autores donen resposta als punts anteriors, l'article podria ser una aportació útil, tot i que no estic del tot segur que les dades de què disposen hi donen prou suport. Em permet suggerir que, en lloc d'una tesi sobre el rendiment, plantegen un estudi descriptiu de la percepció de les famílies, que és la part més sòlida del treball i, curiosament, la menys destacada."}, {"text": "Una última observació, que no afecta la valoració de fons: la bibliografia en valencià es redueix a tres títols, tots d'una mateixa autora, cosa que em costa de creure en un camp que compta amb una producció tan nodrida. Potser no és que no n'hi haja més."}]}, "exercises": [{"q": "Quina és la valoració global que fa el revisor del manuscrit?", "o": ["Reconeix mèrits reals, però considera que les conclusions no estan prou fonamentades en les dades", "El troba molt sòlid i només en demana canvis de forma", "El considera irrecuperable i en recomana el rebuig", "El valora positivament, però lamenta que l'equip editorial no li done més temps"], "e": "L'elogi inicial queda matisat per «Dit això» i per la insistència en les limitacions; demana una «revisió major», no el rebuig ni l'acceptació."}, {"q": "Quina funció té la frase «Hom podria pensar que una nota a peu de pàgina és un lloc ben discret per a una limitació tan central»?", "o": ["Insinuar amb cortesia que les autores han relegat la limitació on menys es nota", "Recomanar que les notes a peu de pàgina s'usen amb més freqüència", "Elogiar la discreció de les autores en tractar els punts febles", "Explicar una convenció de l'editorial sobre les notes"], "e": "L'adjectiu «discret» i el contrast amb «tan central» donen a entendre que la limitació s'ha amagat, sense formular l'acusació."}, {"q": "Per què l'elogi sobre «una familiaritat envejable amb la bibliografia anglosaxona» s'ha de llegir en relació amb l'última observació?", "o": ["Perquè, en conjunt, suggerix que les autores han descuidat la bibliografia pròxima", "Perquè mostra que el revisor també coneix la bibliografia anglosaxona", "Perquè demana que s'elimine la bibliografia anglosaxona", "Perquè afirma que la bibliografia en valencià és de poca qualitat"], "e": "El primer elogi prepara el contrast: tanta literatura estrangera i només tres títols en valencià, de la mateixa autora, deixa veure la crítica."}, {"q": "Quina actitud transmet l'adverbi «curiosament» en l'última frase del cinqué paràgraf?", "o": ["Una lleu crítica: les autores destaquen menys el que millor els ix", "Sorpresa agradable davant d'un resultat inesperat", "Dubte sobre si l'estudi descriptiu és realment sòlid", "Indiferència davant de l'organització del manuscrit"], "e": "«Curiosament» assenyala una incoherència: el millor del treball és precisament allò a què les autores donen menys relleu."}, {"q": "Què dona a entendre el revisor amb «no estic del tot segur que les dades de què disposen hi donen prou suport»?", "o": ["Que, en realitat, considera que les dades no sostenen la tesi", "Que desconeix les dades i necessita demanar-les", "Que està convençut que la tesi és correcta però difícil de provar", "Que prefereix no emetre cap opinió sobre les dades"], "e": "És un eufemisme de cortesia acadèmica: la reserva formal expressa una conclusió negativa."}, {"q": "Què dona a entendre el revisor quan afirma que és «una qüestió de maquetació i no d'intenció» el truncament de l'eix de la figura 2?", "o": ["Que accepta la bona fe de les autores, però ho presenta com un defecte que afavorix la seua tesi", "Que ha comprovat personalment que no hi ha cap intenció de manipulació", "Que la figura s'hauria de suprimir perquè és massa difícil de llegir", "Que la responsabilitat és de l'editorial i no de les autores"], "e": "«Estic segur que» és cortesia irònica: concedix la bona fe, però remarca que l'efecte visual exagera la diferència; per això demana corregir-ho."}, {"q": "Què critica el revisor amb «frases que busquen l'efecte retòric més que la demostració»?", "o": ["Que l'estil afavorix la persuasió en lloc de la prova", "Que les frases són massa llargues i difícils de seguir", "Que s'hi usen termes massa tècnics per a un públic ampli", "Que el text conté faltes d'ortografia i de puntuació"], "e": "Contraposa «efecte retòric» a «demostració»: el problema és que s'argumenta amb recursos d'estil i no amb dades."}]}, {"passage": {"media": "text", "title": "Una carta de recomanació", "lines": [{"text": "A la comissió de selecció de la Mancomunitat de Biblioteques de la Safor. Assumpte: informe sobre la senyora Amparo Ferrandis Gil, aspirant a la plaça de coordinadora de la xarxa."}, {"text": "Em demaneu que informe sobre qui ha treballat cinc anys sota la meua direcció, i ho faig de molt bon grat. Gràcies a la confiança de la comissió, tinc la satisfacció de poder dir quatre paraules sobre una persona a qui estime."}, {"text": "La senyora Ferrandis és puntual: la seua puntualitat és ja proverbial a la biblioteca, i ningú no recorda haver-la vista arribar un sol dia després de l'hora. Mai no ha deixat una tasca sense acabar, encara que no sempre dins del termini que s'havia previst. Té un tracte afable amb el públic infantil, que li ha dedicat més d'un dibuix, i amb els companys ha mantingut sempre una relació correcta."}, {"text": "Domina el catàleg com poques persones. Quan fa dos anys la humitat va afectar el dipòsit, va mostrar una serenitat admirable: va esperar, amb tota la calma, a rebre instruccions. Que cada lector trobe el llibre que busca, ho deu en bona part a la seua memòria prodigiosa de les signatures."}, {"text": "Com a mostra del seu esperit de servici, em limitaré a recordar la campanya «Un llibre, un veí»: la senyora Ferrandis es va ocupar de plastificar els cartells, i ho va fer amb un acabat que els ha sobreviscut a tres hiverns. La idea la va tindre una becària; el disseny, una voluntària; l'èxit, per descomptat, és de tots."}, {"text": "S'ha adaptat sense queixes als canvis informàtics, que ha anat adoptant a mesura que la resta de l'equip deixava de parlar-ne. Hui utilitza el programa de préstecs amb una soltesa que jo mateix li envege, i només requerix ajuda per a les consultes avançades, els informes estadístics i les sol·licituds de subvenció."}, {"text": "Recorde amb simpatia la reunió del 2023 en què l'equip va debatre el nou horari d'estiu: la senyora Ferrandis va opinar que li pareixia bé el que decidira la direcció, i la sessió es va acabar molt abans del que s'havia previst, cosa que tots vam agrair. En cinc anys no m'ha demanat mai un augment, una reunió ni una explicació, i crec que cap de les tres coses no li ha fet falta."}, {"text": "En l'àmbit de les iniciatives, el club de lectura que va proposar el 2021 es va ajornar per falta de recursos, i el 2022 es va tornar a ajornar. Confie que alguna vegada es farà. Pel que fa al seu lloc en l'equip, no recorde que haja discrepat mai en públic d'una decisió meua, cosa que dic, naturalment, com a qualitat."}, {"text": "No seré jo qui dubte de la capacitat de ningú per a assumir responsabilitats; sols afegiré que la senyora Ferrandis ha manifestat sempre un gran apreci per l'estabilitat. Si la comissió valora la tranquil·litat d'una secció per damunt de qualsevol altra consideració, trobarà en ella la candidata ideal. Si fos la meua decisió, em costaria molt separar-me d'una col·laboradora així, i espere que la comissió ho tinga en compte."}, {"text": "Rebeu una salutació cordial de qui no escatima l'elogi quan es mereix."}, {"text": "Josep Miquel Aliaga, director de la Biblioteca Municipal"}]}, "exercises": [{"q": "Quina és la intenció real de qui escriu la carta?", "o": ["Desaconsellar la candidata sense dir-ho de manera explícita", "Recomanar-la amb entusiasme per a la plaça", "Excusar-se perquè no la coneix prou", "Demanar a la comissió que no cobrisca la plaça"], "e": "Només lloa qualitats secundàries i insinua mancances de iniciativa i de criteri: és una recomanació en to elogiós però de contingut desfavorable."}, {"q": "Quin recurs predomina en els elogis de la carta?", "o": ["Lloar qualitats accessòries que no són les que es demanen per al càrrec", "Exagerar els mèrits professionals amb dades concretes", "Comparar la candidata amb altres persones de la biblioteca", "Citar l'opinió positiva dels usuaris"], "e": "Puntualitat, afabilitat o memòria de les signatures no són les competències d'una coordinadora; l'elogi buit és la manera de no recomanar."}, {"q": "Què suggerix l'afirmació que va esperar «amb tota la calma, a rebre instruccions» durant la crisi de la humitat?", "o": ["Que no va tindre iniciativa quan la situació la requeria", "Que va seguir amb precisió el protocol d'emergència", "Que va protegir el dipòsit amb molta eficàcia", "Que va demanar ajuda a una empresa especialitzada"], "e": "La «serenitat admirable» es transforma en retret: davant d'una urgència, esperar ordres és mancar d'iniciativa."}, {"q": "Per què és significatiu que només necessite ajuda per a «les consultes avançades, els informes estadístics i les sol·licituds de subvenció»?", "o": ["Perquè són precisament les tasques centrals d'una coordinació de xarxa", "Perquè són les úniques que fa tot el personal de la biblioteca", "Perquè demostra que l'aplicació informàtica és massa complicada", "Perquè indica que la direcció les fa per ella per costum"], "e": "La llista presenta com a detall menor allò que un coordinador ha de dominar: l'elogi informàtic amaga una mancança."}, {"q": "Per què «cosa que dic, naturalment, com a qualitat» no es pot llegir com un elogi sincer?", "o": ["Perquè l'aclariment i «naturalment» deixen veure que ho considera falta de criteri propi", "Perquè afirma que discrepar en públic és sempre una falta", "Perquè reconeix que ell mateix ha discrepat en públic d'ella", "Perquè demana a la comissió que ho oblide"], "e": "Haver d'explicar que és una qualitat indica el contrari: la subordinació completa al director no és mèrit per a coordinar."}, {"q": "Quin pressupost conté «Si la comissió valora la tranquil·litat d'una secció per damunt de qualsevol altra consideració»?", "o": ["Que per a la coordinació caldrien altres qualitats que ella no té", "Que la comissió només busca persones de caràcter tranquil", "Que la secció actual té molts conflictes interns", "Que la candidata ha demanat un lloc més tranquil"], "e": "La condició «per damunt de qualsevol altra consideració» presuposa que normalment es valoren altres coses, i en aquestes la candidata no destaca."}, {"q": "Com es pot interpretar la darrera frase del penúltim paràgraf, «em costaria molt separar-me d'una col·laboradora així»?", "o": ["Com una manera cortesa d'oferir un motiu personal per a no ascendir-la", "Com una promesa que la nomenarà ell mateix", "Com una crítica als altres membres de l'equip", "Com un avís que pensa dimitir si no la nomenen"], "e": "Sembla un elogi afectuós, però dona a la comissió un argument per a deixar-la on és; és un exemple de cortesia que desactiva la recomanació."}]}]},
  {"id": "0f3bf410-dc28-5aba-81bc-d0b2c1cded3c", "category": "comprensio_escrita", "type": "c2_ce_instruccions", "sort_order": 2, "title": "Instruccions públiques complexes", "name": "Guies de tramitació, avisos i protocols llargs", "content": "Comprén amb detall instruccions públiques llargues i complexes sobre qualsevol procediment, amb condicions, excepcions, terminis i obligacions diferents segons cada cas (2.1).", "icon": "📋", "color": "#CFD8DC", "blocks": [{"passage": {"media": "text", "title": "Guia de tramitació de la llicència d'obra menor", "lines": [{"text": "1. Quan cal sol·licitar-la. Es consideren obres menors les reformes interiors que no afecten elements estructurals, la substitució de paviments i d'instal·lacions, el pintat de façanes i la col·locació de bastides o contenidors a la via pública per un període inferior a un mes. No són obres menors, encara que ho semblen, les que modifiquen la façana o la distribució dels buits d'un edifici inclòs en el Catàleg de béns protegits, les que tanquen terrasses ni les que dividixen un habitatge en dos. Eixes obres requerixen llicència d'obra major, amb projecte tècnic visat, i se segueix un altre procediment."}, {"text": "2. Qui pot sol·licitar-la. El propietari de l'immoble o, en el seu nom, la persona que l'ocupe en règim de lloguer, sempre que aporte l'autorització escrita del propietari. Si l'immoble pertany a una comunitat de propietaris i les obres afecten elements comuns (façana, patis, canonades generals), cal adjuntar també el certificat de l'acord de la junta. Si només afecten l'interior de l'habitatge, n'hi ha prou amb comunicar-ho per escrit a l'administrador, sense que la tramitació depenga de la resposta d'este."}, {"text": "3. Documentació. a) Formulari normalitzat, degudament emplenat. b) Descripció de les obres, amb un pressupost desglossat. c) Fotografies de l'estat actual. d) Justificant del pagament de la taxa, que es calcula aplicant el 2,5 % al pressupost, amb un mínim de 40 euros. e) Si s'ha d'ocupar la via pública, plànol de l'espai que s'ocuparà i durada prevista. No cal tornar a aportar els documents que ja estiguen en poder de l'Ajuntament, però s'ha d'indicar en quin expedient consten."}, {"text": "4. Presentació i terminis. La sol·licitud es pot presentar per via telemàtica o a la seu de l'Ajuntament. Dins dels quinze dies hàbils següents a la presentació, els servicis tècnics poden requerir l'esmena de defectes; el sol·licitant disposa aleshores de deu dies hàbils per a esmenar-los i, si no ho fa, s'arxivarà l'expedient. El requeriment d'esmena interromp el còmput del termini de resolució fins que es complisca. A l'efecte d'estos terminis, són inhàbils els dissabtes, els diumenges i els festius."}, {"text": "5. Resolució i silenci. L'Ajuntament resoldrà en un termini de trenta dies hàbils des que la documentació estiga completa. Si transcorreguts estos dies no s'ha notificat cap resolució, la llicència s'entén concedida, llevat que les obres afecten la via pública o un bé protegit; en eixos supòsits, el silenci té sentit negatiu, és a dir, la sol·licitud s'entén denegada."}, {"text": "6. Execució. La llicència caduca si les obres no s'inicien en sis mesos des de la notificació. Es pot sol·licitar una única pròrroga, de la mateixa durada, sempre abans que acabe el primer termini. Les obres que produïsquen soroll només es podran fer de dilluns a divendres, de les 8 a les 20 hores."}, {"text": "7. Finalització. Dins dels quinze dies naturals següents a l'acabament de les obres, cal comunicar-ho a l'Ajuntament, que podrà fer-ne una inspecció. L'incompliment d'esta obligació pot comportar una sanció, però no afecta la validesa de la llicència ja concedida."}, {"text": "8. Casos particulars. Si les obres es fan en un local comercial, cal afegir la declaració responsable d'activitat; si qui sol·licita és una persona jurídica, s'ha d'aportar l'escriptura de poders; i, si les obres afecten instal·lacions de gas o d'electricitat, l'Ajuntament pot exigir un certificat tècnic. Estes exigències s'afigen a les anteriors, no les substituïxen."}]}, "exercises": [{"q": "Una arrendatària vol substituir el paviment interior de l'habitatge sense tocar l'estructura. Què ha d'aportar, a més del formulari i la documentació general?", "o": ["L'autorització escrita del propietari", "Un projecte tècnic visat", "El certificat de l'acord de la junta de la comunitat", "Un plànol d'ocupació de la via pública"], "e": "És obra menor; l'arrendatari pot sol·licitar-la en nom del propietari, però ha d'aportar-ne l'autorització escrita. El projecte visat és propi de les obres majors."}, {"q": "Una propietària vol canviar la grandària dels balcons de la façana d'un edifici inclòs en el Catàleg de béns protegits. Com ha de tramitar-ho?", "o": ["Com a obra major, amb projecte tècnic visat", "Com a obra menor, perquè només afecta la façana", "Com a obra menor, però amb la pròrroga automàtica", "Només comunicant-ho a l'Ajuntament en acabar"], "e": "Modificar la distribució dels buits de la façana d'un edifici catalogat no és obra menor, encara que semble xicoteta."}, {"q": "En un edifici amb comunitat de propietaris, una veïna només reformarà la cuina, sense tocar canonades generals. Quina és la seua obligació envers la comunitat?", "o": ["Comunicar-ho per escrit a l'administrador, sense esperar-ne resposta", "Obtindre el certificat de l'acord de la junta", "Demanar l'autorització de tots els veïns de la planta", "Cap, perquè la comunitat no intervé en les obres interiors"], "e": "Si les obres només afecten l'interior, basta la comunicació escrita, i la tramitació no depén de la resposta de l'administrador."}, {"q": "El pressupost d'unes obres és de 1.200 euros. Quina taxa s'ha de pagar?", "o": ["40 euros", "30 euros", "1.200 euros", "No hi ha taxa per davall de 2.000 euros"], "e": "El 2,5 % de 1.200 és 30 euros, però hi ha un mínim de 40 euros."}, {"q": "Una sol·licitud d'obra menor, que inclou una bastida de tres setmanes a la via pública, no ha obtingut cap resposta passats trenta dies hàbils amb la documentació completa. Què se n'ha d'entendre?", "o": ["Que s'ha denegat, perquè afecta la via pública", "Que s'ha concedit, com en les altres obres menors", "Que l'expedient s'ha arxivat", "Que cal tornar a presentar la sol·licitud"], "e": "El silenci és positiu en general, però negatiu quan les obres afecten la via pública o un bé protegit."}, {"q": "Una persona va rebre la notificació de la llicència fa quatre mesos i encara no ha començat les obres. Quin és el termini màxim del qual disposa, si fa els tràmits oportuns?", "o": ["Huit mesos més, si sol·licita la pròrroga abans que acabe el primer termini", "Dos mesos més, sense necessitat de sol·licitar res", "Sis mesos més, mitjançant una pròrroga renovable", "Quatre mesos més, si paga una segona taxa"], "e": "El primer termini és de sis mesos (en queden dos) i se'n pot demanar una única pròrroga de sis més abans que acabe: 8 mesos des de hui."}, {"q": "Una obra acabada no s'ha comunicat a l'Ajuntament. Quina conseqüència té?", "o": ["Pot haver-hi una sanció, però la llicència continua sent vàlida", "La llicència queda anul·lada amb efectes retroactius", "L'obra es considera major i s'ha de tornar a tramitar", "L'Ajuntament està obligat a fer una inspecció"], "e": "L'incompliment pot comportar una sanció, però no afecta la validesa de la llicència; la inspecció és només una possibilitat («podrà»)."}]}, {"passage": {"media": "text", "title": "Instruccions per a la població davant d'episodis de pluges intenses", "lines": [{"text": "Objecte i abast. Estes instruccions s'apliquen a tot el terme municipal quan l'Agència estatal de meteorologia declare l'avís groc, taronja o roig per precipitacions, o quan el Centre de Coordinació Municipal emeta un avís propi per risc d'inundació. L'avís propi pot ser més restrictiu que l'estatal i, en eixe cas, preval."}, {"text": "Avís groc. No es restringix cap activitat, però es recomana evitar els desplaçaments innecessaris per rambles, barrancs i camins rurals, i no estacionar en lleres seques ni en soterranis. Les persones que cuiden xiquets o majors han de comprovar que tenen el mòbil carregat i que saben on es troba el punt de reunió del seu barri."}, {"text": "Avís taronja. Se suspén l'activitat lectiva presencial en els centres situats en zona inundable, que figuren en el plànol annex; en els altres centres es manté, però no es poden fer eixides escolars ni activitats al pati. Les empreses haurien de facilitar el treball a distància o permetre que la plantilla isca amb temps suficient per a ser a casa abans que s'agreuge la situació. Els transports públics poden reduir la freqüència sense avís previ."}, {"text": "Avís roig o missatge ES-Alert. Ningú no ha de desplaçar-se amb vehicle, llevat de les emergències. Qui es trobe dins d'un vehicle, ha de deixar-lo i buscar el lloc més elevat que tinga a prop. No s'ha de baixar mai a un garatge o a un soterrani per a retirar un cotxe: l'aigua pot pujar en pocs minuts i bloquejar les escales. Les persones que viuen en plantes baixes de zones inundables han de pujar a un pis superior sense esperar cap indicació per megafonia."}, {"text": "Rambles, barrancs i passos baixos. No s'han de travessar a peu ni amb vehicle, encara que l'aigua semble poca: una làmina d'aigua d'uns trenta centímetres pot fer flotar un cotxe i una corrent forta pot arrossegar una persona. Si el pas està inundat, la decisió de no passar és definitiva i no depén de la prisa que es tinga ni de la presència d'altres vehicles que ja hi han passat."}, {"text": "Persones amb mobilitat reduïda o que depenen d'aparells elèctrics. Han d'avisar el servici municipal d'atenció social amb la màxima antelació possible, preferentment durant l'avís groc, perquè se'ls puga assignar un recurs d'evacuació. Qui utilitze respiradors o equips amb bateria els ha de tindre carregats des del primer avís, sense esperar que es talle el subministrament elèctric. Els animals de companyia podran acompanyar els seus propietaris als punts de reunió, sempre que vagen subjectes."}, {"text": "Informació i comunicacions. Els únics canals oficials són el web municipal, el perfil institucional de les xarxes socials i els missatges ES-Alert. No es recomana difondre imatges ni rumors, que poden generar desplaçaments perillosos. El telèfon 112 s'ha de reservar per a emergències amb risc per a la vida; per a qualsevol altra consulta, hi ha una línia d'informació municipal."}, {"text": "Fi de l'avís. L'emergència no es considera acabada quan deixa de ploure, sinó quan el Centre de Coordinació Municipal ho comunique de manera expressa. Fins aleshores, no s'han d'obrir les comportes de soterranis ni de garatges i s'han d'evitar els trams pròxims a rambles, perquè l'aigua pot continuar baixant hores després de l'últim ruixat."}]}, "exercises": [{"q": "L'Agència estatal de meteorologia declara l'avís groc, però el Centre de Coordinació Municipal en declara un de propi, més restrictiu. Quin s'aplica?", "o": ["El municipal, perquè en cas de conflicte preval", "L'estatal, perquè té prioritat jeràrquica", "El més recent, siga quin siga", "Cap dels dos fins que es publique una resolució conjunta"], "e": "El text diu que l'avís propi pot ser més restrictiu que l'estatal i que «en eixe cas, preval»."}, {"q": "En una situació d'avís taronja, un col·legi que no figura en el plànol de zones inundables:", "o": ["Manté les classes, però sense eixides ni activitats al pati", "Suspén l'activitat lectiva presencial", "Manté totes les activitats amb normalitat", "Només suspén les classes de l'ensenyament infantil"], "e": "La suspensió afecta els centres en zona inundable; els altres continuen, però amb les restriccions d'eixides i d'activitats al pati."}, {"q": "Què diferència la manera com el text s'adreça als centres lectius i a les empreses en l'avís taronja?", "o": ["Als centres els imposa una suspensió; a les empreses els fa una recomanació", "Les empreses estan obligades a tancar i els centres, no", "Només els centres poden decidir si apliquen o no la mesura", "No hi ha cap diferència, perquè totes dues són obligacions"], "e": "«Se suspén» és una obligació; «haurien de facilitar» és un condicional de recomanació, no una imposició."}, {"q": "En avís roig, una persona que viu en una planta baixa d'una zona inundable sent soroll d'aigua al carrer, però la megafonia no ha dit res. Què ha de fer?", "o": ["Pujar a un pis superior de seguida", "Esperar la megafonia abans de moure's", "Eixir a veure fins on arriba l'aigua", "Baixar al garatge a protegir el cotxe"], "e": "Les instruccions diuen que s'ha de pujar «sense esperar cap indicació per megafonia»."}, {"q": "Per què s'adverteix que no s'ha de baixar a un garatge a retirar un cotxe?", "o": ["Perquè l'aigua pot pujar molt de pressa i impedir l'eixida", "Perquè els garatges estan prohibits durant l'avís roig", "Perquè el cotxe no es pot salvar de cap manera", "Perquè el soterrani està dins de la zona inundable del plànol"], "e": "El text justifica la prohibició amb el risc que l'aigua bloquege les escales en pocs minuts."}, {"q": "Un conductor veu que un altre cotxe acaba de travessar un pas baix inundat. Què ha de fer ell segons les instruccions?", "o": ["No travessar-lo, perquè l'exemple d'altres vehicles no canvia la decisió", "Travessar-lo, si l'aigua no passa de la meitat de la roda", "Travessar-lo, però només a poca velocitat", "Esperar vint minuts i tornar-ho a mirar"], "e": "La decisió de no passar és definitiva i no depén «de la presència d'altres vehicles que ja hi han passat»."}, {"q": "Ha deixat de ploure fa una hora i fa sol, però encara no hi ha cap comunicat municipal. Què es recomana?", "o": ["Continuar com si l'avís seguira vigent, evitant soterranis i trams pròxims a rambles", "Tornar a l'activitat normal, perquè ha acabat la pluja", "Anar a mirar l'estat de les rambles per a informar els veïns", "Telefonar al 112 per a confirmar que l'avís ha acabat"], "e": "L'avís només s'acaba quan es comunica expressament; l'aigua pot continuar baixant hores després, i el 112 és només per a emergències vitals."}]}]},
  {"id": "9bb41c93-311e-5062-9bab-946f57120dd3", "category": "comprensio_escrita", "type": "c2_ce_literaris", "sort_order": 3, "title": "Textos literaris i estil", "name": "Narrativa breu, novel·la i diferències d'estil", "content": "Entén textos literaris (contes, narrativa curta, novel·la) i en aprecia el punt de vista, el to, el sentit figurat i les diferències d'estil entre autors i registres (2.1).", "icon": "📖", "color": "#F8BBD0", "blocks": [{"passage": {"media": "text", "title": "Conte: El colomer", "lines": [{"text": "Quan Vicent va morir, la família va acordar, amb la unanimitat que només dona la covardia, que algú havia de fer-se càrrec dels coloms. Tots em miraren a mi. Jo, que durant quaranta anys havia dit que aquell terrat era una cort amb pretensions, vaig dir que sí amb la veu ben clara, com qui accepta una condemna que ja esperava."}, {"text": "La primera setmana els vaig alimentar amb la mateixa fúria amb què netejava els vidres. Posava el pinso al plat, canviava l'aigua, agafava l'escombra, i no els mirava. Eren vint-i-tres, i tots tenien nom, perquè Vicent no concebia que un ésser capaç de tornar a casa des de quatre-cents quilòmetres no el tinguera. Jo els deia «tu», amb un to de reclamació de deutes."}, {"text": "El que més ràbia em feia era el silenci. Quaranta anys sentint-los, al matí, a les cinc, quan Vicent ja s'havia alçat, ja era dalt, ja els parlava d'una manera que a mi no m'havia parlat mai: amb paciència. Ara que ell no hi era, el murmuri dels coloms havia quedat convertit en un soroll de fons, i el colomer semblava una església després d'un funeral: net, ordenat i inútil."}, {"text": "La tercera setmana, la Pepa del segon va pujar a dir-me que els coloms embrutaven els estenedors. Li vaig respondre que això ja ho sabia, que sempre havia pensat el mateix, i que si volia que els fera fora a espentes, tenia l'escala a l'esquerra. Em vaig quedar tan sorpresa de la meua pròpia resposta que vaig haver d'asseure'm sobre la caixa del pinso."}, {"text": "Un d'ells, el gris de la taca blanca a l'ala, que Vicent anomenava «el Ministre» perquè no feia res sense consultar-ho tres vegades, es va posar al meu costat. No em va mirar; mirava l'horitzó, cap on sempre mira un colom que ha de tornar. Vaig pensar que era la mirada d'un home que se n'havia anat, i que això, al capdavall, era una manera d'estar ací. No ho vaig dir. A les dones de la meua edat se'ns educa perquè pensem una cosa i en diguem una altra, i amb els anys la distància entre totes dues ha crescut tant que ja no cal parlar."}, {"text": "A l'octubre va haver-hi la prova de Requena. El president de la societat va vindre a casa amb una carpeta i la cara dels qui porten males notícies. Em va dir que, com que el colomer estava a nom de Vicent, havia de decidir si inscrivia els coloms o si renunciava. Vaig dir que ho pensaria. Ho vaig dir amb una serietat tan gran que se'n va anar convençut que renunciaria."}, {"text": "La nit abans, vaig pujar al terrat amb una llanterna. Vaig comptar els coloms i en vaig trobar vint-i-tres. Els vaig comptar una altra vegada, per si de cas, i van ser vint-i-tres també. Aleshores vaig obrir la porta del colomer, i no per a deixar-los anar, perquè ells sabien tornar, sinó per a deixar que la nit els entrara als ulls, com feia ell."}, {"text": "A les nou del matí vaig telefonar al president. Li vaig dir que inscrivira els vint-i-tres, que no esperara de mi cap discurs, i que ja el cridaria si hi havia res a signar. Va dir que d'acord, i després, amb una veu que no li coneixia, va afegir: «Ho hauria fet igual». No vaig saber què respondre. Vaig penjar i vaig pujar a agafar l'escombra, que és com jo sé dir les coses."}]}, "exercises": [{"q": "Quin és el to dominant de la narradora quan parla dels coloms i del seu marit mort?", "o": ["Una ironia seca que dissimula l'afecte i el dolor", "Una nostàlgia oberta i sentimental", "Una indiferència sincera envers l'afició del marit", "Una indignació contra la societat de colombaires"], "e": "Parla amb fredor i sarcasme («una cort amb pretensions», «reclamació de deutes»), però els fets que narra delaten tendresa i dolor."}, {"q": "Què critica la narradora amb l'expressió «la unanimitat que només dona la covardia»?", "o": ["Que els familiars acorden la solució perquè cap no vol fer-se càrrec del problema", "Que tota la família estava d'acord a vendre els coloms", "Que ningú no entenia l'afició de Vicent", "Que els parents es temien una discussió amb ella"], "e": "La unanimitat no és fruit d'una convicció, sinó de la covardia: tots miren cap a ella perquè ningú no vol assumir la càrrega."}, {"q": "Què suggerix la comparació «com qui accepta una condemna que ja esperava»?", "o": ["Que ella ja sabia que acabaria encarregant-se'n i que ho accepta amb resignació", "Que sent un gran remordiment per alguna falta passada", "Que cap altre familiar volia ajudar-la", "Que els coloms li causaven por"], "e": "«Que ja esperava» indica que la conclusió li era previsible; la forma de condemna vol ser irònica, però no sembla cap rebuig real."}, {"q": "Com s'ha d'interpretar la imatge del colomer com «una església després d'un funeral»?", "o": ["Com un espai ordenat i solemne que ha perdut el sentit que tenia", "Com un lloc ple de gent que ve a donar el condol", "Com un lloc sagrat que la narradora respectava", "Com un lloc brut que cal netejar amb urgència"], "e": "L'església després d'un funeral està neta i en silenci, però buida de la presència que li donava sentit; així queda el colomer sense Vicent."}, {"q": "Què revela l'escena amb la veïna Pepa?", "o": ["Que la narradora ja ha començat a defendre els coloms sense adonar-se'n", "Que la narradora mantenia mala relació amb tots els veïns", "Que la veïna tenia raó en la queixa dels estenedors", "Que la narradora volia vendre el terrat"], "e": "La seua pròpia resposta la sorprén tant que s'ha d'asseure: ha pres partit pels coloms, cosa que no hauria fet abans."}, {"q": "Quin sentit té que, la nit abans de la prova, òbriga la porta del colomer «per a deixar que la nit els entrara als ulls, com feia ell»?", "o": ["Repetix un ritual del marit com a forma d'homenatge", "Prepara la fugida dels coloms", "Comprova que la porta no s'encalla", "Els habitua a la foscor per a la competició"], "e": "No és una acció pràctica: reproduïx un gest de Vicent, que és la manera que té ella d'estar-hi present sense dir-ho."}, {"q": "Per què acaba el conte amb «vaig pujar a agafar l'escombra, que és com jo sé dir les coses»?", "o": ["Perquè expressa els seus sentiments amb accions i no amb paraules", "Perquè vol acabar aviat la conversa amb el president", "Perquè considera que els coloms estan massa bruts", "Perquè dubta si ha fet bé de decidir"], "e": "Resumix el to del conte: la narradora no formula els afectes (ho ha dit a propòsit del pensar una cosa i dir-ne una altra); els fa visibles en el treball."}]}, {"passage": {"media": "text", "title": "Dos fragments sobre el tancament d'una fàbrica de joguets", "lines": [{"text": "Fragment A"}, {"text": "El divendres, a les tres de la vesprada, va tancar la fàbrica. Ningú no va fer cap discurs. El gerent va signar uns papers a l'oficina i va eixir per la porta del darrere. A les tres i deu, les dones del taller de pintura es van llevar la bata, la van plegar i la van deixar sobre la cadira. Eren cinquanta-sis. Hi havia un cartell nou a l'entrada: «Tancat per cessament d'activitat». L'havien escrit a màquina."}, {"text": "A les quatre ja no quedava ningú al pati, llevat del vigilant, que es va asseure sobre una caixa de cartó i va encendre una cigarreta. Dins la nau, les màquines seguien al seu lloc. A la cadena número dos hi havia encara tres-cents cavallets de fusta, mig pintats, per a una comanda que ja no eixiria. Algú havia deixat una ampolla d'aigua oberta damunt del banc. A la paret, el calendari seguia a la setmana anterior."}, {"text": "A les set, el vigilant va tancar la porta amb dues voltes de clau. Va mirar el rellotge, va calcular quant li quedava de contracte i se'n va anar caminant cap a casa. Va passar per la plaça. Hi havia tres o quatre homes a la barra del bar, parlant de futbol. Va demanar un cafè. L'endemà va ploure."}, {"text": "El dilluns, el tècnic de l'ajuntament va visitar la nau amb una carpeta. Va prendre mesures, va fer fotografies i va apuntar uns números. Va dir que podria ser un magatzem, o un aparcament. Cap dels dos que l'acompanyaven va dir que li pareguera bé. Va escriure l'adreça de l'ajuntament al full, va tancar la carpeta i se'n va anar a dinar. Va escriure l'adreça de l'ajuntament al full, va tancar la carpeta i se'n va anar a dinar."}, {"text": "Fragment B"}, {"text": "Nosaltres, que havíem nascut dins del xiulet de les set, no vam saber què fer amb el silenci. La fàbrica va tancar els ulls aquella vesprada —les finestres, vull dir, que durant seixanta anys havien estat oberts de bat a bat sobre el riu— i va deixar caure sobre el poble tot el seu alé vell de pintura i de cola, com un animal que sap que ha arribat la seua hora i no vol que ningú el veja plorar. Ningú no va dir res; ningú no va dir que les nostres mans encara feien olor de vernís; ningú no va gosar pronunciar la paraula que tots teníem a la boca i que se'ns va quedar a la gola, com un os."}, {"text": "Dins, a la nau, els cavallets de fusta, mig pintats, miraven el sostre amb una paciència que no era d'este món. Tenien les galtes de rosa i la crinera verda i els ulls encara per fer, i esperaven, com esperen els xiquets que no han nascut, que algú acabara d'inventar-los. I jo pensava que hi ha coses que no moren quan se'n deixa la fabricació, sinó quan s'oblida el nom de qui les va fer; i pensava que, si el món és just, algun dia algú obrirà una porta, i entrarà la llum, i els cavalls, d'un bot, travessaran l'horitzó de la vall, al galop, cap a un mar que ningú no els ha ensenyat."}]}, "exercises": [{"q": "Quina diferència fonamental d'estil hi ha entre els dos fragments?", "o": ["El A descriu els fets des de fora amb frases breus; el B els viu des de dins amb imatges i períodes llargs", "El A és més emotiu perquè usa la primera persona del plural", "El B és més objectiu perquè enumera les dades amb precisió", "El A empra un lèxic més culte i el B més col·loquial"], "e": "A és un registre objectivista de parataxi curta; B és líric, amb personificacions, sintaxi llarga i narrador implicat."}, {"q": "Quin efecte produïx la frase curta «Eren cinquanta-sis.» enmig de la descripció del fragment A?", "o": ["Dona una dada freda que deixa al lector la reflexió sobre el cost humà", "Serveix per a comptar els personatges que apareixeran després", "Introduïx una crítica explícita al gerent", "Marca el ritme d'una enumeració comptable"], "e": "Sense comentar-ho, el narrador deixa que la xifra siga qui parle: és un recurs de contenció (understatement)."}, {"q": "Què aporta el detall «L'havien escrit a màquina» sobre el cartell?", "o": ["Subratlla la fredor administrativa amb què es tanca una història de seixanta anys", "Indica que la fàbrica era molt antiga i no tenia ordinadors", "Mostra que els treballadors van col·laborar en l'escriptura", "Explica per què el cartell no es va llegir bé"], "e": "El contrast entre el que significa el tancament i el tràmit burocràtic que el comunica és una manera implícita de criticar."}, {"q": "Amb quin sentit acaba el fragment A amb «L'endemà va ploure»?", "o": ["Amb una frase neutra que, sense dir-ho, contagia a l'entorn la tristesa", "Amb una dada meteorològica que explica el descans dels treballadors", "Amb una referència irònica a la sequera de l'any", "Amb una prolepsi que anuncia la inundació de la fàbrica"], "e": "El narrador evita qualsevol adjectiu emotiu i confia que el lector relacione la pluja amb l'estat d'ànim col·lectiu."}, {"q": "Quina funció té la metàfora «va tancar els ulls, les finestres» del fragment B?", "o": ["Personificar la fàbrica com un ésser viu que agonitza", "Descriure amb precisió l'arquitectura de la nau", "Anunciar que els vidres es van trencar", "Distingir l'interior de l'exterior del poble"], "e": "L'alé, els ulls i el plor atribueixen a la fàbrica un cos i una consciència: és una personificació que dona al tancament dimensió de mort."}, {"q": "Què denota el narrador del fragment B amb «Nosaltres, que havíem nascut dins del xiulet de les set»?", "o": ["Que parla com a veu col·lectiva implicada, no com a observador", "Que el poble era massa petit per a tindre veus diferents", "Que els obrers van fer un acte de protesta conjunta", "Que el relat es recorda molts anys després"], "e": "La primera persona del plural situa el narrador dins de la comunitat afectada, al contrari del narrador distant del fragment A."}, {"q": "En l'última frase del fragment B, quin sentit tenen els cavalls que travessen l'horitzó «cap a un mar que ningú no els ha ensenyat»?", "o": ["Un desig de futur i de llibertat per al que ha quedat inacabat", "Una descripció realista de la comanda que s'ha de lliurar", "Una burla sobre els joguets que no es venen", "La resignació davant de la inutilitat de la fàbrica"], "e": "Els joguets s'ixen de la seua condició d'objectes: el text els dona un destí imaginari, a l'oposat de la conclusió pràctica («magatzem o aparcament») del fragment A."}]}]},
  {"id": "57a1f016-8736-56df-9252-95fb4a088a79", "category": "comprensio_escrita", "type": "c2_ce_varietats", "sort_order": 4, "title": "Varietats i registres", "name": "Parlars valencians, registres col·loquials i llengua popular", "content": "Comprén textos escrits en varietats diatòpiques (parlars valencians), diafàsiques (registres formal i col·loquial) i diastràtiques (llengua popular), i en interpreta el valor i l'adequació (2.1).", "icon": "🗣️", "color": "#FFE0B2", "blocks": [{"passage": {"media": "text", "title": "Relat: El dinar de la mascletà", "lines": [{"text": "La mascletà va acabar a les dos i, a les dos i deu, la tia Amparo ja tenia la taula parada al terrat. Havia convocat tota la família, des del cosí Roc, que viu a Castelló i havia vingut en tren de bon matí amb la seua filla Mariló, fins a l'oncle Quico, que no s'havia mogut de la cadira de vímet des que va començar la calor. El fum de la pólvora encara es ficava pels balcons, i tots parlaven a crits, perquè les orelles els brunzien."}, {"text": "La taula no estava parada com se para una taula, sinó com s'organitza un setge: l'arròs al mig, els plats de ceràmica pintats a mà, una botella de vi amb l'etiqueta mig arrancada i un cistell de pa que ningú no gosava tocar abans que la tia donara el senyal. Davant de cada cadira hi havia un tovalló doblegat amb les inicials del seu propietari, brodades per la iaia fa mig segle."}, {"text": "—Seieu, seieu —va dir la tia—. Tu, Roc, ahí no, que ahí hi ha corrent d'aire; vine ací, al costat de l'oncle, i així el vigiles. He parat la taula a les dos i deu per a que ningú no es queixe que es menja tard."}, {"text": "—Xe, quina mascletà —va dir Roc, mentre s'asseia—. Jo he flipat amb el final. Tia, el cabàs que em vas demanar, l'hi he deixat al passadís."}, {"text": "—Mentrimentres jo escalfe l'arròs, vosaltres aneu a per les cadires de l'estudi —va ordenar la tia—. I tu, Mariló, ves a per pa i a pel vi, que ací no n'hi ha ni gota."}, {"text": "—El que no hi ha és respecte per a un home de la meua edat —va rondinar l'oncle Quico—. Tots corrent i jo ací assegut. I tu, Roc, sempre has sigut un ximplet; ho pense des que et vaig vore plorar davant d'un coet."}, {"text": "—Sempre diu el mateix, l'oncle —va comentar Mariló, en veu alta, per a que ho sentiren tots—. Si no li donen faena, es posa malalt; i si li'n donen, també."}, {"text": "—Ho has dit tu —va concloure la tia. L'oncle va fer veure que no havia sentit res, que era la manera que tenia de guanyar totes les discussions."}, {"text": "Mentre portaven les cadires, la Mariló va trobar en un calaix de la cuina una fotografia de la comunió de tots els cosins, amb els vestits de marí i les corbates massa curtes. Va preguntar qui era el de la creu al coll."}, {"text": "—El que fa cinc començant per l'esquerra —va dir la tia, sense mirar—. Eixe és Roc, que ja tenia cara de no haver trencat mai un plat."}, {"text": "El dinar va durar fins a les cinc. Cap a eixa hora, Roc va mirar el rellotge amb un gest teatral. —Nosaltres se n'anirem devers les sis —va dir—, que demà hi ha faena i no vull que la nit ens agafe al tren."}, {"text": "—Sempre diu que se'n va i mai no se'n va —va murmurar l'oncle Quico a l'orelleta de la tia, que va somriure sense dir res i va tornar a omplir-li el got."}]}, "exercises": [{"q": "En «Tu, Roc, ahí no, que ahí hi ha corrent d'aire; vine ací», què indica l'ús d'«ahí» enfront d'«ací»?", "o": ["«Ahí» assenyala el lloc on es troba o s'ha de posar l'interlocutor; «ací», el de qui parla", "«Ahí» és una variant col·loquial d'«ací» sense diferència de significat", "«Ahí» indica un lloc llunyà tant de qui parla com de qui escolta", "«Ahí» s'ha usat per error, perquè la forma correcta seria «aquí»"], "e": "Els parlars valencians distingixen tres graus: ací (prop del qui parla), ahí (prop del receptor o a distància intermèdia) i allí/allà (lluny)."}, {"q": "La forma «l'hi he deixat» de Roc, que ve de Castelló, és característica de:", "o": ["Els parlars valencians més septentrionals, que usen hi per a li davant d'un altre pronom", "La llengua popular de qualsevol territori, sense relació amb el lloc", "Un registre formal escrit", "Els parlars meridionals, que han conservat així el pronom lo"], "e": "El valencià septentrional (i la resta del domini) diu «l'hi he deixat»; així el text caracteritza Roc segons el seu origen sense dir-ho."}, {"q": "Per què l'autor posa en boca de Roc «Nosaltres se n'anirem devers les sis» en lloc d'«Ens n'anirem cap a les sis»?", "o": ["Per a reproduir la parla espontània, perquè en registres poc formals nos+ne passa a se", "Perquè és l'única forma correcta en valencià escrit formal", "Perquè Roc no domina la gramàtica del valencià", "Perquè vol marcar una diferència entre generacions"], "e": "La GVB admet «se n'anirem» en registres poc formals o en reproduccions de llengua natural, i no en els formals."}, {"q": "Quin matís aporta «devers les sis»?", "o": ["Una hora aproximada, amb una preposició viva en el valencià meridional", "Una hora exacta i inajornable", "Una hora anterior a les sis", "Un lloc: «en direcció a les sis»"], "e": "«Devers» expressa direcció i també aproximació temporal: «cap a les sis»; és característic del valencià meridional."}, {"q": "L'expressió col·loquial «ves a per pa», que usa la tia, pot substituir-se en un registre formal per:", "o": ["«Ves a buscar pa»", "«Ves a pel pa a la fleca»", "«Ves-hi per pa»", "«Ves-te'n a comprar-ne»"], "e": "La seqüència a + per és col·loquial; es pot evitar amb un verb més precís, com buscar o comprar."}, {"q": "Quina interpretació cal donar a «El que fa cinc començant per l'esquerra» en la fotografia?", "o": ["La persona que ocupa el cinqué lloc, comptant des de l'esquerra", "Cinc persones que apareixen a l'esquerra", "La persona que fa cinc anys que és a la foto", "El cinqué cosí en edat, sense importar on s'ha situat"], "e": "En llengua col·loquial els cardinals fan de valor ordinal a partir del quart («el que fa cinc» = el cinqué)."}, {"q": "Quin efecte tenen «Xe», «flipat» i «ximplet» en les paraules dels personatges?", "o": ["Marquen una parla familiar, espontània i afectuosa entre parents", "Indiquen la voluntat dels personatges d'insultar-se", "Mostren que els personatges tenen poca formació lingüística", "Són arcaismes que el narrador ha recuperat d'una font escrita"], "e": "«Xe» (interjecció), «flipar» (col·loq.) i «ximplet» (fava, innocent) pertanyen al registre col·loquial i donen un to de confiança, no d'hostilitat."}]}, {"passage": {"media": "text", "title": "Tres versions d'una mateixa excusa", "lines": [{"text": "Pau Soriano va arribar a la ferreteria de l'oncle a les deu i quart, en lloc de les nou. La nit abans havia anat a un concert i no havia tornat a casa fins a les quatre. Al llarg del matí, el mateix retard va tindre tres explicacions. La ferreteria, que ocupava un baix de la plaça des de feia quaranta anys, obria a les nou en punt, i Ramon era un home que sabia comptar les hores pel moviment de les persianes dels veïns."}, {"text": "A l'amic, per telèfon, davant de la porta: «Tio, no t'ho creuràs, flipa. Ahir, concert fins a les tres, i el despertador, ni cas. M'he despertat a dos quarts de nou, he eixit pel carrer amb una sabata de cada color i, quan he vist el meu cap, he fet cara d'angelet. Em pixe de riure només de pensar-hi, però no li ho diguem a ningú, eh?»"}, {"text": "A la iaia Pilar, que viu a la porta del costat i el va veure arribar amb el cabell sense pentinar: «Res, iaia, que hui l'autobús ha vingut ple i n'he hagut d'esperar un altre.» —«Aixina?, ximplet, que a mi no m'enganyes: jo vaig criar tres fills i sé quan una mentida ve de lluny. Vine ací, menja't este bocí de coca que t'he guardat, i no et diré res al teu pare. Però, la pròxima vegada, millor que m'ho contes a mi, que la paciència no se m'acaba. I no te'l menges tan de pressa, que t'ofegaràs i, a més, em quedaré sense motius per a renyar-te.»"}, {"text": "Al seu oncle Ramon, ja a dins, amb la mà a la gorra i la veu de les grans ocasions: «Bon dia, Ramon. Em veig en l'obligació de disculpar-me pel retard d'esta matinada, que obeïx a una incidència en el servici de transport públic que utilitze habitualment. Ja he recuperat els minuts perduts i he deixat reposats els paquets del magatzem.»"}, {"text": "L'oncle Ramon el va escoltar sense alçar el cap de l'albarà. —Gràcies, Pau —va dir—. Només un detall: se sol dir que les incidències del transport públic són molt desagradables, però no sabia que deixaren una polsera de colors al canell. Pau va fer un pas arrere i va estirar la màniga de la camisa, però ja era tard."}, {"text": "—No et preocupes —va afegir l'oncle, i va somriure per primera vegada en tot el matí—. Jo també vaig anar a eixe concert, i no vaig arribar a les nou. El que passa és que jo soc el cap, i els caps no hem de donar explicacions."}, {"text": "Aquella vesprada, quan van baixar la persiana, Ramon va traure del calaix del taulell un paper arrugat: l'entrada del concert, que Pau s'havia deixat damunt de la caixa. —Ací la tens —va dir—. La pròxima vegada, guarda-la millor, que les proves es perden molt de pressa. Pau la va agafar i, com qui accepta un acord que no cal escriure, va prometre que l'endemà arribaria abans de les nou. I ho va complir, que és cosa més rara que les incidències del transport públic."}]}, "exercises": [{"q": "Quina és la combinació correcta de registre i interlocutor en les tres versions de l'excusa?", "o": ["Col·loquial i desimbolt amb l'amic; popular i afectuós amb la iaia; formal i cerimoniós amb l'oncle Ramon", "Formal amb l'amic; col·loquial amb la iaia; popular amb l'oncle", "Popular amb l'amic; formal amb la iaia; col·loquial amb l'oncle", "Col·loquial amb els tres, però amb més o menys velocitat"], "e": "Pau adapta el registre a cada interlocutor (variació diafàsica): «tio, flipa» amb l'amic, «iaia, aixina, ximplet» amb la iaia i una sintaxi cerimoniosa amb el cap."}, {"q": "Quin valor té «tio» en «Tio, no t'ho creuràs»?", "o": ["Un tractament col·loquial d'un home, sense relació de parentiu", "El títol d'un oncle de Pau", "Un insult mitigat per l'ús", "Un mot de respecte envers una persona més gran"], "e": "El DNV el marca com a col·loquial: tractament d'un home encara que no siga parent de qui el diu."}, {"q": "Què comunica l'expressió «em pixe de riure només de pensar-hi»?", "o": ["Que li fa molta gràcia, en un registre familiar i exagerat", "Que té una necessitat fisiològica", "Que tem les conseqüències del retard", "Que pensa en una altra mentida"], "e": "«Pixar-se de riure» és una locució col·loquial que vol dir riure molt; és pròpia del tracte entre iguals."}, {"q": "Quin matís dona la iaia a «ximplet» quan li diu «Aixina?, ximplet»?", "o": ["Afecte i una reprensió suau per haver cregut que podia enganyar-la", "Una ofensa greu per haver-li mentit", "L'admiració per la seua astúcia", "Una sorpresa sincera per la seua ingenuïtat"], "e": "El DNV defineix ximplet com a fava, innocent; en boca de la iaia, que no s'ho creu, és una reprensió afectuosa: el considera massa ingenu per a enganyar-la."}, {"q": "Quin efecte produïx el llenguatge formal de la disculpa a Ramon («obeïx a una incidència en el servici de transport públic»)?", "o": ["Distància cerimoniosa que fa evident l'excusa preparada, i que accentua la ironia posterior", "Cortesia sincera i adequada que convenç l'oncle", "Una confusió deliberada per a evitar parlar de la nit", "Una imitació del llenguatge administratiu que Ramon sempre usa"], "e": "El registre formal, innecessari entre oncle i nebot, ressalta que és un guió; per això l'escena torna irònica quan es descobrix la polsera."}, {"q": "Què dona a entendre l'oncle Ramon amb «no sabia que [les incidències] deixaren una polsera de colors al canell»?", "o": ["Que sap que Pau va estar al concert i no s'ha cregut l'excusa", "Que li ha de pagar una indemnització pel transport", "Que vol prohibir-li que porte joies a la feina", "Que desconeix l'ús de les polseres als concerts"], "e": "L'ironia consistix a fingir una ignorància que denuncia la mentida: la polsera és la prova del concert."}, {"q": "Per què Pau no pot reaccionar amb el mateix registre davant de l'oncle que davant de l'amic?", "o": ["Perquè la relació jeràrquica i la situació de feina exigixen un registre més formal", "Perquè l'oncle no entén les expressions col·loquials", "Perquè el valencià formal és preferible en qualsevol context", "Perquè l'amic és de més edat que l'oncle"], "e": "L'adequació depén del tipus de relació i de la situació; la variació diafàsica no és falta de coherència, és competència comunicativa."}]}]},
  {"id": "44edc8f6-b48e-5f2c-bd1b-b89d9bbc04a2", "category": "comprensio_escrita", "type": "c2_ce_colloquial", "sort_order": 5, "title": "Expressions col·loquials i idiomàtiques", "name": "Locucions i frases fetes de poc ús en context", "content": "Entén expressions col·loquials i idiomàtiques, fins i tot les d'ús menys general, i en deduïx el sentit a partir del context i del to del text (2.1).", "icon": "💬", "color": "#E1BEE7", "blocks": [{"passage": {"media": "text", "title": "Crònica d'un casament de poble", "lines": [{"text": "Quan la meua neboda Núria va anunciar que es casava, el seu pare, que és home de poques paraules i de pocs estalvis, va dir que per a l'única filla es podia tirar la casa per la finestra. Jo, que el conec de fa quaranta anys, vaig pensar que tirar la casa per la finestra, en el seu cas, volia dir llogar un menjador sense cadires de plàstic."}, {"text": "La meua cunyada ho veia d'una altra manera. «Estem estirant més el braç que la mànega», repetia, «i després, qui ho paga?» Però el seu marit, a força de sentir-ho, havia acabat per fer l'orni: quan ella parlava de números, ell contemplava la lluna per la finestra amb una atenció admirable."}, {"text": "El banquet es va fer en una alqueria de la Plana. El menjador estava ple de gom a gom: cent huitanta convidats, un xiquet damunt de cada cadira i un violinista que ningú no sabia qui havia convidat. L'arròs, anunciat a la carta com a «cuina de mercat», va arribar a taula amb un color que l'oncle Vicent, cuiner retirat, va qualificar de «sospitós»; i quan li van oferir un vi que, segons el cambrer, era «de collita pròpia», l'oncle va murmurar que ja n'hi havia prou de donar-nos gat per llebre. El vi, tot s'ha de dir, era de pa i raïm."}, {"text": "La mare del nuvi, que té mala bava i una veu que travessa les parets, va felicitar els pares de la núvia amb la mateixa efusió amb què es felicita l'adversari que acaba de guanyar-te una partida. Les dues àvies, per contra, que durant trenta anys no s'havien parlat per una qüestió de tovalloles, es van asseure juntes i, en dos entrepans, ja eren carn i ungla. Ningú no va saber mai què havia passat entre elles; l'enigma de les tovalloles encara forma part de la mitologia de la família."}, {"text": "Els discursos van ser el moment més aventurat. L'amic del nuvi, que parla a tort i a dret des dels huit anys, va ficar en un sol brindis la mare de Núria, un antic xicot de la núvia, l'equip de futbol del poble i la reforma de la plaça; quan va callar, hi havia un silenci en què es podia sentir cremar una espelma."}, {"text": "A l'hora del pastís va ploure a bots i barrals. El fotògraf, un pardal descuat que n'ha vist de tots colors, va col·locar els nuvis davall de la pèrgola i va fer la millor foto de la nit: ella, ell i un ruixat que feia de teló de fons. Núria diu que, davant d'eixa fotografia, tota la tensió dels mesos anteriors no va valdre una figa."}, {"text": "Quan vam tornar cap a casa, el pare de la núvia anava callat. Li vaig preguntar si havia valgut la pena. «Mira», va dir, «he gastat el que no tenia i he sentit coses que no oblidaré en la vida. Però quan l'he vista ballar amb el seu avi, he pensat que la casa, per la finestra o per la porta, era el de menys.» I va somriure, com qui ha pagat un preu alt i no vol que ningú ho note."}]}, "exercises": [{"q": "Què implica la frase «tirar la casa per la finestra, en el seu cas, volia dir llogar un menjador sense cadires de plàstic»?", "o": ["Que fins i tot la seua despesa més gran és molt moderada, perquè és una persona estalviadora", "Que el pare no pensava gastar res en el casament", "Que va llogar el millor menjador de la comarca", "Que va demanar ajuda econòmica a la família del nuvi"], "e": "L'expressió significa gastar molt, però el narrador la rebaixa amb ironia: pel caràcter del pare, el gran desembós és només evitar les cadires de plàstic."}, {"q": "Quan la cunyada diu «Estem estirant més el braç que la mànega», què vol dir?", "o": ["Que estan gastant més del que es poden permetre", "Que han de repartir millor les feines entre els familiars", "Que s'esforcen molt per quedar bé amb els convidats", "Que no han previst prou menjar per a tothom"], "e": "La locució significa gastar més del que es pot; l'actitud de la cunyada és de preocupació econòmica."}, {"q": "Què significa que el marit «havia acabat per fer l'orni»?", "o": ["Que feia veure que no sentia el que li incomodava", "Que sabia callar quan era el moment oportú", "Que havia acabat contemplant la natura", "Que ho ignorava perquè no entenia els números"], "e": "Fer l'orni és fer el desentés per conveniència; ací, quan ella parla de diners, ell mira la lluna per a no haver de respondre."}, {"q": "En «El menjador estava ple de gom a gom», què es vol expressar?", "o": ["Que no hi cabia ningú més", "Que tots els convidats menjaven amb ganes", "Que el menjador havia sigut decorat amb cura", "Que el soroll no deixava parlar"], "e": "De gom a gom és «ple de banda a banda»: la sala estava totalment plena, amb xiquets damunt de les cadires."}, {"q": "Per què l'oncle Vicent diu que ja n'hi havia prou de «donar-nos gat per llebre»?", "o": ["Perquè sospita que els servixen una cosa inferior fent-la passar per una altra de millor", "Perquè no vol que li servisquen més carn de caça", "Perquè creu que el cambrer menteix sobre el preu", "Perquè prefereix menjar arròs en lloc de carn"], "e": "Donar gat per llebre és enganyar fent passar una cosa per una altra; ell sospita del vi «de collita pròpia» i de l'arròs."}, {"q": "Quin matís aporta «el vi era de pa i raïm»?", "o": ["Que era de baixa qualitat, malgrat la presentació", "Que anava acompanyat de pa i de raïm", "Que era un vi dolç, típic de les festes", "Que era un vi molt valorat entre els experts"], "e": "De pa i raïm és de poca qualitat o de poc valor; contrasta amb la descripció «de collita pròpia» del cambrer."}, {"q": "Què es diu de l'amic del nuvi amb «parla a tort i a dret des dels huit anys»?", "o": ["Que parla sense reflexionar, i per això pot ofendre sense voler", "Que parla amb correcció gramatical des de menut", "Que parla de tot amb molt de coneixement", "Que només parla quan algú li ho demana"], "e": "A tort i a dret és sense mirar si hi ha raó o sense reflexionar; el brindis, amb la mare, l'antic xicot i la reforma de la plaça, ho confirma."}]}, {"passage": {"media": "text", "title": "L'assemblea de la cooperativa", "lines": [{"text": "L'assemblea extraordinària de la cooperativa del poble es va convocar a les set de la vesprada i a les huit encara s'hi estaven comptant les cadires. Al davant, la mesa: el president, Tonet, que fa vint anys que pasta i feny la junta a la seua manera, i el tresorer, Aureli, el burro de faena de tots els exercicis, que du els comptes com qui du una creu."}, {"text": "El punt del dia era la fusió amb la cooperativa del poble veí. El gerent, un xicot molt ben pentinat arribat de la ciutat, va explicar que el projecte era «ambiciós, rendible i, a més, ecològic». Va parlar quaranta minuts, amb diapositives, i quan va acabar, un vell soci d'ulls curiosos, Salvador, que ha sigut pardal descuat tota la vida, va alçar la mà i va dir: «Això és molt bonic, xic, però a mi no m'agrada que em vulguen fer creure que un burro vola.»"}, {"text": "Va haver-hi murmuris. El president, que té per costum no dir ni gos què fas ahí a qui l'incomoda, va fer com si no haguera sentit res i va passar a la intervenció següent. Va parlar Josep, el de les tarongeres del camí vell, que ho va aprofitar per a pixar fora de test: va començar parlant de l'aigua de la séquia, va passar al preu del gasoil, després a la seua cunyada, i va acabar explicant com el seu gos sabia obrir la porta del corral. Quan va acabar, Tonet li va donar les gràcies amb un posat que volia dir: «No sé què has dit, però ho has dit amb passió.»"}, {"text": "Salvador va tornar a alçar la mà. «Al meu poble», va dir, «sempre s'ha dit que segons el pardal, la gàbia. Si vos ajunteu amb els del poble de damunt, haureu d'afegir tres camions, dos magatzems i un director que no coneix els bancals. I tot això, amb quin diner? Estem estirant més el braç que la mànega abans de començar.» L'aplaudiment va ser curt, però sincer."}, {"text": "La votació va ser ajustada: seixanta-quatre vots a favor, seixanta-quatre en contra i un en blanc. En una situació així, un home com Tonet podia haver cridat que tot era una conspiració; però, per sort seua, el reglament preveia que el vot del president valdria doble en cas d'empat. «Has tingut més sort que un gos que s'ofega», li va dir Aureli a cau d'orella. Tonet va somriure i va dir que ell mai no havia dubtat. La clàusula figurava al reglament des de feia més de trenta anys, i ningú no recordava haver-la vista aplicada mai; fins i tot els qui la van redactar es van mirar sorpresos, com si hagueren sentit un tro en un cel sense núvols."}, {"text": "El gerent, que s'havia anat acostant a la porta mentre durava el recompte, va decidir que era un bon moment per a tocar el dos. Abans d'eixir, un soci jove li va dir que, a la propera assemblea, hauria d'aportar números i no diapositives. Salvador, assegut al darrer banc, va afegir només una frase, que va quedar escrita a l'acta amb una nota a peu de pàgina: «Qui fia amb els ulls tancats del seu pa farà sopes.»"}]}, "exercises": [{"q": "Què es pot deduir de la caracterització del tresorer com a «burro de faena de tots els exercicis»?", "o": ["Que fa la feina més pesada i no en rep gaire reconeixement", "Que és poc intel·ligent i comet molts errors de còmput", "Que cobra molt per la seua feina", "Que només treballa quan hi ha assemblea"], "e": "Un burro de faena és una persona molt laboriosa que fa les feines més pesades; el text ho completa amb «du els comptes com qui du una creu»."}, {"q": "Amb quina intenció diu Salvador «no m'agrada que em vulguen fer creure que un burro vola»?", "o": ["Mostrar-se escèptic davant d'unes promeses que li semblen exagerades", "Elogiar la imaginació del gerent", "Demanar que s'explique millor l'aspecte ecològic", "Fer una broma sobre el cabell del gerent"], "e": "Fer creure que un burro vola és fer creure coses absurdes o impossibles; Salvador qüestiona la credibilitat del projecte amb un humor sec."}, {"q": "Què implica que el president «no diga ni gos què fas ahí» davant dels murmuris?", "o": ["Que els ignora deliberadament, sense respondre'ls", "Que els respon amb duresa", "Que els demana silenci amb un gest", "Que els tradueix a la resta de socis"], "e": "No dir ni gos què fas ahí és no fer cas ni dir res a algú; el president evita el conflicte ignorant-lo."}, {"q": "Per què es diu que Josep va «pixar fora de test» en la seua intervenció?", "o": ["Perquè va divagar i va parlar de coses que no tenien relació amb la fusió", "Perquè va dir coses que ofenien el president", "Perquè va criticar el projecte amb molta duresa", "Perquè es va equivocar de dia a l'hora de votar"], "e": "Pixar fora de test és eixir-se'n de la qüestió; el text ho il·lustra amb la successió de temes: séquia, gasoil, cunyada, gos."}, {"q": "Què vol dir Salvador amb «segons el pardal, la gàbia»?", "o": ["Que els projectes s'han d'ajustar a les proporcions i als mitjans reals", "Que els pardals necessiten gàbies més grans", "Que no es pot canviar la manera de fer les coses", "Que els socis majors tenen la darrera paraula"], "e": "La locució s'usa per a indicar que cal adaptar les coses a l'ús o a les proporcions degudes; l'argument de Salvador és que la cooperativa no té mitjans per a créixer tant."}, {"q": "Què insinua Aureli quan diu a Tonet «Has tingut més sort que un gos que s'ofega»?", "o": ["Que Tonet s'ha salvat gràcies a una regla que l'afavoria", "Que Tonet no mereix el càrrec que ocupa", "Que la votació va ser fraudulenta", "Que a Tonet li falta energia per a dirigir"], "e": "Tindre més sort que un gos que s'ofega és tindre molta sort; el vot doble del president era el que li permetia eixir de l'empat."}, {"q": "Quin sentit té l'última frase de Salvador, «Qui fia amb els ulls tancats del seu pa farà sopes»?", "o": ["Que qui es confia sense comprovar res assumirà les conseqüències de la seua decisió", "Que qui no té prou diners passarà gana", "Que cal repartir les sopes entre tots els socis", "Que es pot confiar plenament en les propostes dels altres"], "e": "Combina dues locucions: amb els ulls tancats (amb plena confiança) i del seu pa farà sopes (assumirà les conseqüències); és un advertiment al gerent i als qui el voten."}]}]},
  {"id": "b9e1d60f-2b37-5770-9583-8a3205536cca", "category": "comprensio_escrita", "type": "c2_ce_implicit", "sort_order": 6, "title": "Allò que no es diu", "name": "Pressuposicions, sobreentesos, ironia, ambigüitats i el·lipsis", "content": "Capta les pressuposicions, els sobreentesos, el to (ironia, sarcasme, humor) i tot allò que no es diu de manera explícita: ambigüitats, dobles sentits i el·lipsis (2.1).", "icon": "🕵️", "color": "#C5E1A5", "blocks": [{"passage": {"media": "text", "title": "Tauler de la comunitat: notes d'un mes", "lines": [{"text": "Notes recollides al tauler del vestíbul d'un edifici de València, entre el 2 i el 27 d'octubre."}, {"text": "Nota 1, administració (2 d'octubre). Es recorda als senyors veïns que les bicicletes no poden deixar-se al vestíbul. Agraïm, un any més, la sensibilitat amb què el col·lectiu ha atés esta norma, i en especial les quatre bicicletes que, des de juny, esperen un propietari amb una dignitat exemplar."}, {"text": "Nota 2, 2n A (5 d'octubre). Les bicicletes són dels nostres fills, que ja no viuen ací. Estarem encantats de retirar-les quan se'ns indique on es poden deixar. Recordem que el local de trasters, aprovat en junta el 2019, continua, segons l'administració, «en estudi». Nosaltres també vam estudiar, però ens van dir que això acabava amb un títol."}, {"text": "Nota 3, administració (8 d'octubre). Informem que el projecte del local de trasters es troba en mans de la comissió d'obres, que es reunirà quan siga oportú. Ens complau comprovar que la comunitat ha rebut amb tanta atenció les nostres comunicacions. Així mateix, es prega als veïns que no utilitzen el tauler per a polèmiques personals, i que, quan ho facen, almenys ho signen amb el seu nom."}, {"text": "Nota 4, 5é B (11 d'octubre). Proposem que la comissió d'obres es reunisca abans de la jubilació dels seus membres. Recordem, per si ajuda, que la mitjana d'edat de la comissió és de setanta-un anys, i que el president actual va ser designat quan encara es feien servir cabines telefòniques."}, {"text": "Nota 5, 3r B (12 d'octubre). L'ascensor, que va arribar a l'edifici amb la promesa d'una revisió anual, ha complit esta promesa, que sapiguem, almenys una vegada: el 1996. Preguem a qui visite els pisos alts que, per si de cas, porte una ampolla d'aigua i bon humor."}, {"text": "Nota 6, anònima (15 d'octubre). Bicicletes al vestíbul: quatre. Veïns que les utilitzen: cap. Veïns que es queixen: tots. Veïns que fan alguna cosa: ja ho direu vosaltres."}, {"text": "Nota 7, 1r A (20 d'octubre). Algú s'ha endut la bicicleta roja del vestíbul. Si ha sigut un veí, moltes gràcies. Si ha sigut un lladre, també."}, {"text": "Nota 8, 4t A (22 d'octubre). Atesa la sospita expressada en una nota anterior, aclarim que la bicicleta roja era nostra. La vam retirar a les tres de la matinada perquè no molestara ningú. Aprofitem per a saludar els veïns de la festa del terrat de la mateixa hora, que no eren pocs, i per a dir-los que, des del quart, se sent tot: les paraules i la música, que almenys era bona."}, {"text": "Nota 9, presidenta de la comunitat (25 d'octubre). Com a presidenta, vull deixar clar que mai no he dit que el local de trasters no es faça. He dit que no es farà mentre jo siga presidenta, cosa que, vist el ritme de les eleccions, és un compromís de futur. Aprofite l'ocasió per a recordar que la quota d'este trimestre ja ha vençut, i que l'estimació del veïnat és la nostra millor garantia."}, {"text": "Nota 10, administració (27 d'octubre). Atesa la desaparició d'una bicicleta, esta administració ha obert una investigació interna. Mentrestant, i per motius de seguretat, s'han retirat totes les notes anteriors. Gràcies per la comprensió. Per cert, les bicicletes continuen al vestíbul."}]}, "exercises": [{"q": "Què pressuposa l'expressió «un any més» en la nota 1?", "o": ["Que la norma no s'ha complit mai, i que l'agraïment és irònic", "Que la comunitat sempre ha respectat la norma", "Que les bicicletes són noves cada any", "Que l'administració ha canviat el reglament durant l'any"], "e": "«Un any més» presenta l'incompliment com a repetit; combinat amb «sensibilitat» i «dignitat exemplar», l'agraïment és sarcàstic."}, {"q": "Què vol dir realment el 2n A amb «Nosaltres també vam estudiar, però ens van dir que això acabava amb un títol»?", "o": ["Que un estudi que mai no s'acaba no és un estudi, sinó una excusa de l'administració", "Que es proposen estudiar el projecte ells mateixos", "Que critiquen la formació dels membres de la comissió", "Que els seus fills van acabar els estudis"], "e": "Si estudiar dona un resultat final (un títol), un projecte «en estudi» des de 2019 que no té resultat és una excusa; el sarcasme apunta a la dilació."}, {"q": "Què comunica l'administració amb «es reunirà quan siga oportú»?", "o": ["Una vaguetat deliberada que evita comprometre's amb cap data", "Un compromís inminent amb la reunió", "Una subordinació de la comissió als desitjos dels veïns", "Una amenaça velada als veïns que protesten"], "e": "L'absència de data i el condicional «quan siga oportú» són una evasiva burocràtica: no hi ha cap compromís real."}, {"q": "Per què la nota 4 esmenta que el president va ser designat «quan encara es feien servir cabines telefòniques»?", "o": ["Per a suggerir, amb ironia, que fa molt de temps que ocupa el càrrec i que la comissió no es renova", "Per a elogiar l'experiència del president", "Per a demanar que s'instal·len telèfons al vestíbul", "Per a proposar un homenatge a l'antiga companyia telefònica"], "e": "El detall de les cabines, junt amb «mitjana d'edat de setanta-un anys», vol dir que l'estructura és antiga i immobilista."}, {"q": "Què s'ha elidit i què es dona a entendre en «Veïns que les utilitzen: cap. Veïns que es queixen: tots»?", "o": ["Que ningú no usa les bicicletes, tots es queixen i ningú no actua", "Que tots els veïns usen les bicicletes encara que es queixen", "Que els veïns que es queixen són els propietaris de les bicicletes", "Que les queixes han arribat a l'administració però no se n'ha fet cas"], "e": "L'el·lipsi del verb en la sèrie en fa una llista de contrastos; el final, «ja ho direu vosaltres», acusa tots d'inacció, inclosa l'administració."}, {"q": "Per què fa gràcia la nota 7, «Si ha sigut un veí, moltes gràcies. Si ha sigut un lladre, també»?", "o": ["Perquè agraïx igualment el fet que s'han endut la bicicleta que feia nosa, siga qui siga", "Perquè dona les gràcies al lladre per la seua honestedat", "Perquè demana que es denuncie la desaparició", "Perquè minimitza el valor de la bicicleta robada"], "e": "El sobreentès és que la bicicleta molestava: agrair el lladre equival a agrair el veí. L'humor ve de l'equiparació inesperada."}, {"q": "Quin sentit irònic té la nota 10?", "o": ["Presenta com a mesura de seguretat retirar les notes dels veïns, mentre el problema real, les bicicletes, continua sense solució", "Afirma que ha obert una investigació, però no té personal per a fer-la", "Anuncia la desaparició de les bicicletes quan encara són al vestíbul", "Demana la comprensió dels veïns pel retard en l'ordenació de les bicicletes"], "e": "L'administració actua sobre les queixes (les retira) i no sobre la causa; el «Per cert» final i l'«investigació interna» per una sola bicicleta subratllen el contrast."}]}, {"passage": {"media": "text", "title": "L'entrevista", "lines": [{"text": "Aleix s'havia presentat a l'entrevista amb el currículum en una carpeta de plàstic i un posat de molta seguretat. La sala d'espera, amb tres cadires i una planta de plàstic, feia pensar més en un dentista que en una empresa de restauració, però ell no s'hi va fixar. La dona de recursos humans, Sonia Vidal, tenia davant un full que deia «Gestor/a de cartes». L'anunci no explicava gaire més. Ell s'havia fet les seues idees; ella, les seues."}, {"text": "—Aleix, vegem —va dir Sonia—. Té experiència amb cartes?"}, {"text": "—Molta. Des dels deu anys. Al principi, amb els avis; després, amb professionals."}, {"text": "—Perfecte. I què és el que més li agrada de les cartes?"}, {"text": "—La tensió. L'instant en què descobrixes la teua. —Va somriure—. I les cares dels altres."}, {"text": "—Entenc —va dir Sonia, que va apuntar a la llibreta: «Sensibilitat amb el client»—. L'horari és de nit i els caps de setmana."}, {"text": "—I amb el ritme de feina, com se les arregla? —va preguntar Sonia, mentre repassava el full."}, {"text": "—Bé. Si hi ha algun problema, el resolc a la taula, amb calma i a la vista de tots."}, {"text": "—Millor així —va dir ella—. Ací no volem que res es resolga a les cuines."}, {"text": "—Perfecte, em va bé. Sempre he jugat de nit."}, {"text": "—Jugat?"}, {"text": "—Treballat, vull dir. Sempre he treballat de nit."}, {"text": "Sonia va alçar una cella, però va decidir que era un lapsus d'estil i va passar a la pregunta següent: —I què farà quan els clients es queixen que no els agrada el que hi ha?"}, {"text": "—Ho he vist moltes vegades —va dir Aleix—. Cal tindre paciència. Si la mà és mala, no es pot fer res; l'important és no donar-ho a vore."}, {"text": "—Ja —va dir ella, que no havia entés res d'això però ho va assentir amb autoritat—. A la companyia tenim catorze restaurants. Se sent capaç de renovar tota la carta cada temporada?"}, {"text": "—Per descomptat. És la manera de no deixar que els altres et lligen el joc."}, {"text": "Sonia va somriure, perquè allò era exactament el que el director li havia demanat que busqués: algú que entenguera que una carta no és un llibre, sinó una estratègia. Va tancar la llibreta i li va allargar la mà."}, {"text": "—El sou és un fix més un variable segons els resultats de cada local —va dir Sonia—. I els resultats depenen, en bona part, dels clients."}, {"text": "—Llavors m'estimaré més el fix —va dir Aleix—. Amb els clients, mai no es pot saber què porten a la butxaca."}, {"text": "—Això ho diu d'una manera que quasi sembla una amenaça —va riure Sonia."}, {"text": "—És només una descripció —va respondre ell, amb el somriure més innocent que tenia."}, {"text": "—L'espere dilluns a les set. Porte una camisa formal."}, {"text": "Aleix va eixir al carrer amb la sensació d'haver guanyat una partida que ni tan sols sabia que estava jugant. Sonia va tornar al despatx convençuda d'haver contractat el primer candidat en molts mesos que s'havia pres l'ofici de debò. Cap dels dos va pensar que haguera calgut preguntar res més."}]}, "exercises": [{"q": "Quin és el malentés central de l'escena?", "o": ["Ell entén «cartes» com a jocs de cartes; ella, com a cartes de menú dels restaurants", "Ell vol un horari que ella no li pot oferir", "Ella entén que ell és un cuiner, i ell, que és un jugador", "Ell creu que ella és la directora de tots els restaurants"], "e": "Tota la conversa funciona amb la polisèmia de «carta»: per a Sonia, la carta del restaurant; per a Aleix, la baralla."}, {"q": "Per què Aleix corregix «he jugat de nit» per «he treballat de nit»?", "o": ["Perquè nota que «jugar» no encaixa amb una entrevista de feina i adequa el seu discurs", "Perquè es confon amb el verb i no ho sap dir en valencià", "Perquè vol ocultar que té un problema amb el joc", "Perquè Sonia l'havia corregit abans"], "e": "Aleix s'adona del desajust (el lapsus li ha traït l'ofici real) i reformula; Sonia ho interpreta només com una mancança d'estil."}, {"q": "Què interpreta Sonia amb «les cares dels altres»?", "o": ["La sensibilitat davant la reacció dels clients", "L'atenció que posa en els seus companys de feina", "La seua capacitat de recordar la fisonomia de la gent", "La seua habilitat per a negociar amb proveïdors"], "e": "Per a Aleix són els contrincants a la taula; Sonia ho llig com a empatia amb la clientela, i ho apunta com «sensibilitat amb el client»."}, {"q": "Què vol dir realment Aleix amb «Si la mà és mala, no es pot fer res; l'important és no donar-ho a vore»?", "o": ["Que, quan les cartes són dolentes, cal dissimular, perquè això és el que fa un jugador", "Que un bon cambrer ha de ser discret quan el menjar és dolent", "Que els clients han de callar quan no els agrada el plat", "Que el cuiner ha d'amagar els errors de cuina"], "e": "És un consell de jugador de pòquer (el «farol»); Sonia l'aplica sense entendre'l a l'atenció al client, i li pareix correcte."}, {"q": "Quin doble sentit té «és la manera de no deixar que els altres et lligen el joc»?", "o": ["Per al jugador, no revelar l'estratègia; per a Sonia, que la competència no copie la carta del restaurant", "Per al jugador, no perdre cap partida; per a Sonia, no perdre cap client", "Per al jugador, jugar de pressa; per a Sonia, renovar la carta de pressa", "Per al jugador, ocultar les fitxes; per a Sonia, ocultar els preus"], "e": "Una mateixa frase funciona en dues lectures: els jugadors no han de ser previsibles i la competència no ha de poder predir la carta."}, {"q": "Per què el narrador diu que Sonia va contractar «el primer candidat en molts mesos que s'havia pres l'ofici de debò»?", "o": ["Perquè ironitza: ella creu que ha trobat un professional, quan és un malentés", "Perquè elogia sincerament la seua competència professional", "Perquè critica la manca de candidats qualificats", "Perquè suggerix que Aleix s'havia format com a cuiner"], "e": "El narrador sap més que els personatges (ironia dramàtica): l'afirmació és certa només si s'entén de l'ofici de jugador."}, {"q": "Quin recurs principal genera l'humor del text?", "o": ["La ironia dramàtica: el lector sap que els dos personatges parlen de coses diferents", "L'exageració dels fets fins a l'absurd", "El contrast entre els diàlegs i l'entorn físic", "La repetició de les mateixes frases per part dels personatges"], "e": "Els diàlegs funcionen amb dues interpretacions alhora, i només el lector (no els personatges) les veu totes dues."}]}]},
  {"id": "91792387-6063-5d96-9fcf-e62f5da884f3", "category": "expressio_escrita", "type": "c2_ee_relats", "sort_order": 1, "title": "Relats i descripcions d'experiències", "name": "Històries, cròniques i retrats d'experiències viscudes, en l'estil propi de cada gènere", "content": "Escriu històries i descripcions ben elaborades, interessants i fàcilment llegibles d'experiències viscudes, en un estil adequat al gènere (2.3).", "icon": "📖", "color": "#E1BEE7", "exercises": [{"q": "La revista literària d'una associació cultural prepara un número monogràfic titulat «Les cases que ens habiten», dedicat a relats d'experiències viscudes. Escriu un relat en primera persona sobre un lloc (una casa familiar, un pis de lloguer, una barraca, una habitació d'estudiant...) que va marcar un canvi important en la teua vida. Combina la narració dels fets amb la descripció sensorial de l'espai (llum, olors, sorolls) i amb la mirada retrospectiva de qui narra: que es note la distància entre el que vas viure aleshores i com ho entens hui. Tria una estructura que no siga merament cronològica (pots començar per un detall o pel final i explicar-lo després), cuida l'estil literari i tanca el relat sense moralitzar.", "w": {"min_words": 300, "max_words": 400}}, {"q": "Un diari digital publica cada diumenge una secció de cròniques d'experiències viscudes. T'encarreguen la crònica d'un esdeveniment col·lectiu del qual has sigut testimoni (una festa, una manifestació, una final esportiva, una assemblea de veïns, una nit de tempesta al poble...), adreçada a lectors que no hi eren. Reconstruïx l'ambient i els fets amb una mirada observadora i un to lleument irònic: selecciona els detalls més significatius en compte de relatar-ho tot, inclou almenys dues veus d'altres persones (en estil directe o indirecte) i dona a la crònica un títol que cride l'atenció i un tancament que n'oferisca una lectura personal. Evita el to d'acta o de nota de premsa.", "w": {"min_words": 300, "max_words": 350}}, {"q": "Una editorial prepara un llibre col·lectiu de retrats literaris titulat «Persones que ens van ensenyar a mirar». Escriu el retrat d'una persona real que t'ha marcat (una mestra, una veïna, un familiar, un company de faena...). No et limites a enumerar-ne qualitats: construïx el retrat a partir d'una escena concreta i d'un detall físic o gestual que la definisca, mostra el caràcter en compte de dir-lo i fes que es note la relació entre qui escriu i qui és retratat. Adopta un registre cuidat, amb comparacions i imatges originals, i evita els tòpics i els adjectius buits.", "w": {"min_words": 250, "max_words": 300}}]},
  {"id": "4d2d767d-33e1-5b0f-be01-9cf38ab53b3f", "category": "expressio_escrita", "type": "c2_ee_informes", "sort_order": 2, "title": "Crítiques, informes i projectes", "name": "Crítica d'una obra, informe amb recomanacions i projecte d'investigació, amb una estructura lògica i eficaç", "content": "Escriu informes o articles complexos, crítiques de textos literaris o de productes audiovisuals i projectes d'investigació que presenten arguments amb una estructura lògica, eficaç i fluida (2.3).", "icon": "📊", "color": "#BBDEFB", "exercises": [{"q": "La secció de cultura d'una revista especialitzada et demana la crítica d'una obra apareguda en els últims anys i que conegues bé (una novel·la, un llibre de relats, una pel·lícula, una sèrie o un documental). Presenta breument l'obra i el seu plantejament sense revelar-ne el desenllaç; valora de manera raonada tres aspectes (per exemple l'estructura, el llenguatge o la direcció, i el to); situa l'obra en relació amb altres de comparables; distingix els encerts dels punts febles, i justifica cada valoració amb exemples concrets. Acaba amb una recomanació matisada: a qui interessarà i per què. Evita tant el resum encobert com l'elogi o el menyspreu sense arguments, i que es note una veu pròpia i un registre cuidat.", "w": {"min_words": 350, "max_words": 450}}, {"q": "La junta d'un col·legi professional del teu municipi t'encarrega un informe, que també es publicarà com a article d'anàlisi en el butlletí del col·legi, sobre l'ús de la bicicleta com a mitjà de transport. Disposes d'estes dades: en dos anys, els desplaçaments urbans en bicicleta han passat del 6 % a l'11 %; el 38 % de les persones enquestades que no en fan servir afirmen que ho eviten per por al trànsit; la xarxa de carrils bici fa només 4 km i està desconnectada; i hi ha 120 aparcaments per a bicicletes per a una població de 25.000 habitants. Redacta l'informe amb títol, introducció, anàlisi de les dades (sense limitar-te a repetir-les: relaciona-les i interpreta'n les causes), conclusions i tres recomanacions ordenades per prioritat i justificades. Usa un registre formal i objectiu, amb connectors que facen visible l'estructura.", "w": {"min_words": 350, "max_words": 450}}, {"q": "Una universitat convoca ajudes d'iniciació a la recerca i demana un resum ampliat del projecte. Escriu el projecte d'investigació sobre un tema de llengua, literatura, història, educació o societat que et semble rellevant. Ha d'incloure: el títol, la justificació i l'estat de la qüestió (què se sap i què falta per saber), les preguntes o la hipòtesi de partida, els objectius, la metodologia (fonts, corpus o mostra, procediment d'anàlisi), els resultats esperats amb les limitacions previsibles i un calendari de treball de dotze mesos. Argumenta per què el projecte és pertinent i viable, i redacta-ho amb la precisió i la impersonalitat pròpies d'un text acadèmic, amb una estructura clara i sense repeticions.", "w": {"min_words": 350, "max_words": 450}}]},
  {"id": "48bc72b6-748b-5d64-b5c3-03f3460a4a92", "category": "expressio_escrita", "type": "c2_ee_formals", "sort_order": 3, "title": "Textos de formalitat alta", "name": "Article d'opinió, correspondència formal i textos escrits per a ser pronunciats", "content": "Escriu textos de formalitat alta en varietat estàndard que demanen una preparació prèvia notable: textos periodístics (cartes al director, articles d'opinió), correspondència formal a institucions i empreses, i textos escrits per a ser pronunciats, com discursos i parlaments (2.3).", "icon": "🏛️", "color": "#FFE0B2", "exercises": [{"q": "Un diari de comarques obri la secció «Tribuna» a col·laboracions de lectors i proposa el debat «Les festes populars i el dret al descans». Escriu un article d'opinió per a esta secció en què defengues una posició clara sobre com cal conciliar la tradició (pólvora, orquestres, activitats nocturnes) amb el dret al descans dels veïns. Comença amb un títol i una entrada que captiven el lector, desenvolupa dos o tres arguments ben fonamentats, reconeix i rebat almenys un argument de la posició contrària i tanca amb una frase final que es recorde. Pots usar la ironia i els recursos retòrics amb mesura, però sense caure en l'atac personal ni en l'estridència.", "w": {"min_words": 350, "max_words": 450}}, {"q": "L'associació de veïns del teu barri va demanar a l'empresa concessionària del transport urbà que restablira la línia 4, suprimida fa sis mesos. La resposta que ha rebut és cortés però evasiva: lamenta les molèsties, assegura que «s'estudiarà la qüestió en el moment oportú» i no dona cap data ni cap compromís. Com a secretari o secretària de l'associació, escriu la carta de resposta a la gerència de l'empresa. Capta els matisos de l'escrit rebut i deixa'n constància amb una al·lusió fina, sense acusacions directes; recorda el compromís adquirit i les conseqüències de la supressió per als veïns (gent gran, estudiants, pacients del centre de salut); proposa una reunió amb una data límit raonable i indica què farà l'associació si no hi ha resposta. Usa les fórmules d'encapçalament i comiat pròpies de la correspondència formal i un registre molt cuidat, ferm però respectuós.", "w": {"min_words": 300, "max_words": 350}}, {"q": "Has de pronunciar el parlament de comiat en el sopar d'homenatge a una persona que ha dirigit durant trenta anys la banda de música del teu poble i es jubila. Escriu el text complet del parlament, pensat per a ser dit en veu alta davant de familiars, músics i veïns de totes les edats. Inclou una salutació inicial adequada, una anècdota que retrate la persona homenatjada, un fil conductor que done unitat al discurs, algun toc d'humor afectuós i un final emotiu que culmine en un brindis. Adapta l'estil a l'oralitat: frases de longitud variada, repeticions i paral·lelismes que marquen el ritme, interpel·lacions al públic i elements que ajuden a seguir el discurs i a recordar-lo; evita l'emotivitat tòpica i els clixés d'homenatge.", "w": {"min_words": 300, "max_words": 400}}]},
  {"id": "8be28bb5-6fd0-521a-a8a1-cc89d666d707", "category": "expressio_escrita", "type": "c2_ee_resum", "sort_order": 4, "title": "Resumir textos llargs i exigents", "name": "Resum precís d'un assaig argumentatiu i d'un relat literari", "content": "Resumix amb precisió textos narratius literaris, expositius i argumentatius llargs i exigents, destriant-ne la tesi, l'estructura i els arguments o l'argument essencial sense copiar-ne ni valorar-ne res (2.3).", "icon": "📋", "color": "#FFF9C4", "blocks": [{"passage": {"media": "text", "title": "Elogi de la lectura lenta", "lines": [{"text": "Es diu sovint que vivim en l'era de la informació, però potser seria més exacte dir que vivim en l'era de la interrupció. Mai no havíem tingut tants textos a l'abast de la mà i, tanmateix, mai no havíem tingut tan poca paciència per a llegir-ne cap fins al final. La pantalla ens ensenya a saltar d'un paràgraf a un altre, a buscar la paraula clau i a abandonar a la primera dificultat; i, a força de repetir el gest, acabem creient que llegir consistix només en això."}, {"text": "Els qui estudien el fenomen no es posen d'acord sobre la gravetat del diagnòstic. Alguns hi veuen una simple adaptació: el cervell humà ha sigut sempre plàstic, i si fa mil·lennis es va fer lector per a descodificar signes, ara aprén a moure's entre enllaços. Altres adverteixen que esta plasticitat té un preu. Llegir en profunditat, sostenen, no és un do natural sinó una tècnica fràgil que cal exercitar, i les tècniques que no s'exerciten s'atrofien. Qui deixa de practicar-la no se n'adona: continua llegint molt, però cada vegada entén menys del que llig."}, {"text": "Convé, abans de continuar, desfer un malentés. Ningú no defén que la lectura ràpida siga inútil. Per a consultar un horari, localitzar una dada en un informe o triar entre cent resultats d'una cerca, l'ull que explora és insuperable. El problema apareix quan este mode de lectura, que és una eina, s'erigix en l'únic i s'aplica també a textos que no es deixen explorar: una novel·la, un assaig, una llei, la carta d'un amic. Estos textos no guarden la informació en un punt concret; la tenen escampada en el ritme, en les subordinades, en allò que no diuen. Qui els llig a salts en rep el resum i se'n perd la substància."}, {"text": "La lectura lenta, en canvi, és una forma d'hospitalitat. Obliga a concedir a l'autor el temps que necessita per a desplegar una idea, a tolerar una frase que no s'entén a la primera i a tornar-hi. Esta resistència no és un obstacle que cal eliminar: és precisament allò que fa que el lector pense. Quan un text ens ho dona tot mastegat, ens limitem a reconéixer; quan ens exigix, construïm. Per això les lectures que recordem dècades després no solen ser les més fàcils, sinó aquelles en què vam haver de treballar."}, {"text": "Hi ha, a més, una dimensió moral que sovint s'oblida. Llegir a poc a poc un argument contrari al nostre, seguir-lo fins al final abans de rebatre'l, és un exercici de justícia intel·lectual. En les xarxes socials, on tot s'ha de contestar a l'acte i en un parell de línies, esta justícia és impossible, i el debat públic se'n ressent: ens barallem amb versions simplificades dels adversaris perquè no hem tingut paciència per a llegir-ne les versions completes. La polarització no seria només un problema de ressentiments; seria també un problema de velocitat."}, {"text": "Què cal fer, doncs? Alguns proposen tancar els dispositius en un calaix, una solució tan radical com ineficaç, perquè ignora que la tecnologia també pot servir per a llegir bé: un llibre electrònic no és pitjor que un de paper pel fet de ser electrònic. El remei és més modest i més difícil: recuperar l'hàbit. Dedicar cada dia una estona sense interrupcions, sense notificacions ni finestres obertes, a un text que ens supere una mica. Començar amb mitja hora i veure què passa. Els primers dies la ment es resistirà, com el cos quan tornem a l'esport; amb el temps, l'atenció es reconstruïx."}, {"text": "Les escoles hi tenen una responsabilitat enorme. Si el sistema educatiu només premia la lectura utilitària, trobar la resposta i extraure la dada, formarà lectors competents per a l'eficàcia i incapaços per a la comprensió. Calen espais, dins de l'horari, on es llija sense cap finalitat immediata: ni examen, ni fitxa, ni resum. La lectura com a fi en si mateixa té fama de luxe; en realitat és una necessitat cívica, perquè una societat que no pot sostindre l'atenció durant vint pàgines tampoc no podrà sostindre-la durant una legislatura."}, {"text": "Cap d'estes propostes no garantix res. Llegir lentament no converteix ningú en una persona més sàvia ni més bona. Però és la condició necessària perquè uns altres pensaments, més lents i més complexos que els nostres, tinguen lloc en el nostre cap. I això, en un món que ens empeny a respondre abans d'haver comprés, és un acte discret de resistència."}]}, "exercises": [{"q": "Una revista de divulgació educativa publica en cada número el resum d'un assaig de referència perquè el professorat el puga llegir en pocs minuts. Llig l'assaig i escriu-ne el resum per a esta secció. Ha de recollir la tesi central, els arguments que la sostenen (el diagnòstic de la situació, la distinció entre tipus de lectura, la dimensió moral i el paper de l'escola) i les propostes finals, però no les imatges ni les anècdotes que només il·lustren. No seguisques necessàriament l'ordre de l'original: reorganitza la informació de manera que l'estructura lògica del text es veja amb claredat. Formula les idees amb paraules pròpies, sense copiar frases senceres, en un registre formal, i sense afegir-hi cap valoració personal.", "w": {"min_words": 250, "max_words": 300}}]}, {"passage": {"media": "text", "title": "El rellotge de la plaça", "lines": [{"text": "El rellotge de la plaça de Vilarroja es va parar un diumenge de tardor a les quatre i vint, i durant quaranta anys ningú no es va atrevir a tocar-lo. No és que no sabérem arreglar-lo; és que a ningú no li semblava just. Aquella vesprada l'aigua havia pujat per la rambla fins al primer graó de l'església, havia entrat en tres cases i havia deixat, quan es va retirar, un llim roig que va tardar setmanes a desaparéixer de les parets. Les busques, aturades, assenyalaven l'hora exacta de la desgràcia, i el poble havia decidit, sense dir-ho, que era millor tindre un rellotge parat que oblidar."}, {"text": "Leonor Tormo va tornar al poble el dia que va morir el seu pare, Anselm, el rellotger, i va tardar dos mesos a decidir-se a obrir el taller. Havia viscut vint anys a la ciutat, en una oficina on el temps es mesurava en reunions i en terminis, i li costava reconéixer el pas lent de les hores de Vilarroja. Pensava vendre-ho tot. Va ser el batlle qui ho va impedir sense proposar-s'ho, en una visita de condolença que s'allargà més del compte. «Fa quaranta anys el diumenge que ve —va dir, mirant per la finestra cap a la torre—, i hi ha qui voldria que el rellotge tornara a donar l'hora. Tu sabries com.»"}, {"text": "Leonor va respondre que no ho sabia, i era mentida a mitges. Havia crescut entre engranatges i oli fi, i encara recordava el tacte de les rodes dentades; el que no sabia era si tenia dret a tocar el que el seu pare havia deixat intacte durant tota una vida. Perquè Anselm, que reparava rellotges de tota la comarca, s'havia negat sempre a obrir el de la plaça. «Quan el poble el necessite, ja ho dirà», solia contestar, i canviava de conversa."}, {"text": "Va saber el motiu un vespre de març, quan, remenant els quaderns del taller, va trobar un sobre amb el seu nom. Dins hi havia una clau, un croquis de la maquinària de la torre i una carta de poques ratlles. No la va llegir fins a l'endemà, asseguda en l'últim graó de l'escala del campanar, amb els engranatges davant, immòbils i coberts d'una pols tan fina com la farina."}, {"text": "«El rellotge no el va parar l'aigua —deia la carta—. L'aigua va arribar a la meitat de la torre i la maquinària, que és prou més forta del que sembla, va continuar donant les hores fins a mitjanit. El vaig parar jo, tres dies després, quan vaig pujar a veure'l. Vaig posar les busques a les quatre i vint, que és l'hora en què la teua mare va eixir de casa a buscar-te a l'escola i no va tornar. No ho he dit a ningú. El poble ja tenia el seu dolor i no volia llevar-li un motiu per a compartir-lo. Ara fes el que et semble.»"}, {"text": "Leonor es va quedar una bona estona mirant les busques. Va pensar en la dona que no havia conegut més que en una fotografia, i en el pare que havia convertit la seua pena en una xifra penjada sobre tot un poble, perquè tots hi pogueren plorar sense saber que qui plorava, de veritat, era un home en particular. Va pensar també en l'escrúpol de qui havia sigut capaç de callar durant quaranta anys, i es va adonar que aquell silenci no era una mentida: era la manera que el seu pare havia trobat de fer públic el seu dol."}, {"text": "El dia de l'aniversari, la plaça es va omplir. Hi van parlar el batlle, el rector i una xiqueta de l'escola que va llegir uns versos sobre l'aigua. Quan li van fer el gest, Leonor va pujar a la torre amb la clau, i els de baix només van notar que la maquinària tornava a bategar amb un so ferm, com un cor que reprén el ritme. No va avançar les busques fins a l'hora real: les va deixar on estaven i va engegar el pèndol, de manera que el rellotge va reprendre la marxa des de les quatre i vint, com si l'aigua s'haguera retirat just aleshores."}, {"text": "Durant una setmana el poble va viure en un temps propi, retardat, que ningú no va voler corregir, i algú va dir que era la primera vegada que el rellotge anava bé. Només Leonor sabia per què. Després, un diumenge a primera hora, va pujar de nou a la torre i el va avançar fins a l'hora de debò. Ningú no va notar el moment exacte en què el temps va tornar a ser el de tots. Ella va guardar el sobre en la calaixera del taller, entre les eines del seu pare, i no va tornar a obrir-lo."}]}, "exercises": [{"q": "La biblioteca municipal prepara un catàleg amb les fitxes dels relats finalistes d'un premi de narrativa breu, i el jurat necessita llegir-ne un resum precís abans de la deliberació. Llig el relat i escriu-ne la fitxa-resum. Ha de recollir l'argument complet, desenllaç inclòs (el jurat ha de poder entendre'l sense haver llegit l'original), els personatges imprescindibles, els fets decisius en el seu ordre causal i el sentit del rellotge dins de la història, sense detalls ornamentals. Redacta-ho en tercera persona i en present, en un registre formal i objectiu, amb paraules pròpies, sense citacions literals i sense afegir-hi valoracions sobre la qualitat del relat.", "w": {"min_words": 250, "max_words": 300}}]}]},
  {"id": "861a7ad8-55fb-5244-8be3-fda09737b4a1", "category": "expressio_escrita", "type": "c2_ee_apunts", "sort_order": 5, "title": "Apunts de conferències i reutilització", "name": "Apunts detallats d'una conferència i informació reutilitzada en textos nous d'un altre gènere, registre o públic", "content": "Pren apunts detallats i acurats d'una conferència i reutilitza la informació per a elaborar textos nous, de distint àmbit, gènere o registre, adreçats a públics i amb intencions comunicatives diferents (2.3).", "icon": "🎧", "color": "#DCEDC8", "blocks": [{"passage": {"media": "audio", "title": "Conferència: l'aigua com a bé comú", "lines": [{"speaker": "Ponent", "voice": "gina", "text": "Bon dia a totes i a tots, i gràcies per haver vingut. Hui els parlaré d'una qüestió que sembla antiquada i que, en canvi, és d'una actualitat punyent: com van aconseguir les comunitats de regants tradicionals repartir durant segles un recurs escàs sense que el poble s'esberlara. La meua tesi és que el seu èxit no va dependre de la tècnica hidràulica, que era senzilla, sinó d'un disseny institucional molt fi. L'exposició té quatre parts: primer, com funcionava el repartiment; segon, per què va durar tant; tercer, quines pressions el posen hui en perill; i, finalment, què en podem aprendre."}, {"speaker": "Ponent", "voice": "gina", "text": "Comencem pel funcionament. En una séquia tradicional, l'aigua no era de ningú en particular: pertanyia a la comunitat, i cada regant en tenia un dret d'ús lligat a la terra, no a la persona. Qui venia la parcel·la venia també el dret. El repartiment es feia per torns, o tandes: cada propietari rebia l'aigua durant un temps proporcional a la superfície que regava, i quan acabava el seu torn, el següent obria la comporta. Hi havia una figura clau, el síndic, elegit entre els mateixos regants, que anunciava els torns, vigilava les comportes i resolia les discussions. Vull remarcar que la seua autoritat no li venia de cap nomenament extern, sinó de la confiança de la comunitat."}, {"speaker": "Ponent", "voice": "gina", "text": "Per què va durar tant, este sistema? Els estudis assenyalen tres raons. La primera és la simplicitat de les normes: tothom coneixia el seu torn i el seu temps, i no calia ser expert per a saber si algú s'estava apropiant més del que li tocava. La segona és la sanció ràpida i visible: la infracció, com ara obrir una comporta fora de torn, es jutjava en públic i en pocs dies, amb una multa moderada però indiscutible; comptava més la rapidesa de la resposta que la gravetat del càstig. La tercera és la flexibilitat en els anys de sequera: quan l'aigua baixava, els torns no se suprimien, es reduïen proporcionalment per a tots, i això evitava que els qui es trobaven al final de la séquia acabaren sempre sense res."}, {"speaker": "Ponent", "voice": "gina", "text": "Un exemple concret, que em servix per a il·lustrar-ho, és el d'una comunitat que vaig estudiar de prop, amb uns mil dos-cents regants i una xarxa d'uns quaranta quilòmetres de canals. En un any de sequera greu, la junta va decidir reduir els torns en una quarta part. No hi va haver cap conflicte seriós. Segons el síndic, la clau va ser que la decisió es va comunicar abans de començar la temporada, amb les raons i les xifres damunt de la taula. Quan les regles es poden explicar, també es poden acceptar."}, {"speaker": "Ponent", "voice": "gina", "text": "Passem a les pressions actuals. Me'n limitaré a tres. En primer lloc, l'abandonament agrari: cada vegada hi ha menys persones que reguen, i les comunitats tenen dificultats per a renovar els càrrecs i finançar el manteniment. En segon lloc, la pressió urbanística: les parcel·les es converteixen en solars, el dret d'aigua perd sentit i les séquies queden encaixades entre edificis, o simplement soterrades. I en tercer lloc, el canvi climàtic, que fa les sequeres més freqüents i prolongades i posa a prova un sistema pensat per a un règim de pluges que ja no és el mateix. Cal dir, tanmateix, que no totes les pressions pesen igual: segons les dades que he vist, la més decisiva és el relleu generacional, perquè sense persones que hi participen, les normes no tenen qui les faça complir."}, {"speaker": "Ponent", "voice": "gina", "text": "I què en podem aprendre? Proposaré tres idees. La primera: que els béns comuns no són una fatalitat, com sovint se sent dir, sinó que poden gestionar-se bé quan hi ha normes clares i una vigilància exercida per la mateixa comunitat. La segona: que la tradició no s'ha de conservar per nostàlgia, sinó perquè conté solucions provades, i que això justifica protegir no només les infraestructures, sinó també les institucions que les feien funcionar. I la tercera, que per a mi és la més urgent: cal documentar mentre queden testimonis. Moltes d'estes pràctiques no estan escrites; viuen en la memòria dels síndics més majors, i quan ells falten, desapareix una part del saber."}, {"speaker": "Ponent", "voice": "gina", "text": "Resumisc. L'èxit dels regs tradicionals es va deure a un disseny institucional basat en normes simples, sancions ràpides i flexibilitat davant de la sequera; hui l'amenacen l'abandonament agrari, l'urbanisme i el canvi climàtic, i la lliçó és que cal protegir també les institucions i recollir els testimonis abans que es perguen. Moltes gràcies per l'atenció, i si voleu, estic a la vostra disposició per a les preguntes."}]}, "exercises": [{"q": "Treballes en una associació que documenta el patrimoni hidràulic i has assistit a esta conferència. Un company que prepara el dossier d'una candidatura no hi ha pogut anar i necessita la informació. Escolta la conferència i pren apunts detallats. Després, transcriu-los en un text ordenat i ben cohesionat adreçat a ell, tan precís i fidel a l'original que el puga utilitzar com a font: recull la tesi de la ponent, el funcionament del repartiment, les tres raons de la durada del sistema (amb l'exemple de la sequera), les tres pressions actuals i quina és la més decisiva segons la ponent, i les tres idees finals. Respecta l'estructura de la conferència, no hi afegisques opinions teues i deixa clar què és dada i què és valoració de la ponent.", "w": {"min_words": 300, "max_words": 350}}, {"q": "L'associació de regants del teu poble publica un butlletí trimestral adreçat als socis i a les escoles. A partir de la informació de la conferència, escriu per a este butlletí un article de divulgació en un registre proper però cuidat, pensat per a un públic no especialista (regants que coneixen l'ofici i xiquets de dotze anys acompanyats dels seus mestres) que vol entendre per què el sistema de torns va ser tan durador. No reproduïsques l'estructura de la conferència: selecciona les tres o quatre idees més atractives, ordena-les segons un fil propi, explica sense tecnicismes el que calga i inclou un títol, una entrada que captive el lector i almenys una comparació o imatge que ajude a entendre una norma o una pressió. L'article ha de mantindre la fidelitat a les dades i no ha de caure en la nostàlgia.", "w": {"min_words": 300, "max_words": 350}}]}, {"passage": {"media": "audio", "title": "Conferència: ciutats que es refreden", "lines": [{"speaker": "Ponent", "voice": "lluc", "text": "Bona vesprada. Gràcies a la facultat i a l'organització per la invitació. Parlaré de com podem fer les ciutats més habitables en un clima cada vegada més càlid, i defendré una idea que potser sorprén: que la solució no està en més aparells d'aire condicionat, sinó en repensar la superfície de la ciutat. L'exposició té cinc parts: què és l'illa de calor urbana, quines en són les causes, quines mesures funcionen, quines limitacions tenen i com podem avaluar-les."}, {"speaker": "Ponent", "voice": "lluc", "text": "L'illa de calor urbana és la diferència de temperatura entre la ciutat i l'entorn rural proper, que es nota sobretot a la nit. Segons els estudis, pot arribar a ser de dos a cinc graus, i en les nits d'onada de calor això significa que el cos no pot refrescar-se i que el descans empitjora. Cal remarcar que la gent gran, els xiquets i les persones amb malalties cròniques són els qui més ho patixen, i que, dins de la mateixa ciutat, els barris amb menys arbrat i amb més formigó són els més calents. La calor, per tant, no és només un problema ambiental: és també un problema d'equitat."}, {"speaker": "Ponent", "voice": "lluc", "text": "Les causes són bàsicament quatre. Primera, els materials: l'asfalt i el formigó absorbixen la radiació durant el dia i l'alliberen lentament a la nit. Segona, la geometria: els carrers estrets amb edificis alts atrapen la calor i frenen la ventilació. Tercera, la falta de vegetació, que refresca per l'ombra i per l'evapotranspiració. I quarta, la calor residual que genera la mateixa activitat urbana: els motors, els aparells d'aire condicionat, la indústria. L'aire condicionat, de fet, crea un cercle viciós, perquè refresca l'interior i escalfa el carrer."}, {"speaker": "Ponent", "voice": "lluc", "text": "Passem a les mesures. N'hi ha tres grans famílies. La primera és l'arbrat: un carrer ben arbrat pot ser sensiblement més fresc que un de nu, i l'ombra és, de llarg, la mesura més barata i eficaç. La segona són les cobertes i les façanes: les cobertes clares reflectixen la radiació i les cobertes vegetals aïllen i retenen aigua; en les façanes, les plantes enfiladisses actuen com un segon vestit de l'edifici. La tercera, i la que a mi m'interessa més, són els patis escolars: la majoria són grans superfícies de ciment, i convertir-los en espais amb arbres, terra i zones d'ombra refrescaria el barri i, de passada, ensenyaria els xiquets a viure amb el clima. En un projecte pilot que conec, la temperatura de la superfície d'un pati va baixar uns set graus un dia d'estiu després de la reforma."}, {"speaker": "Ponent", "voice": "lluc", "text": "Ara bé, no tot és tan senzill: hi ha limitacions. La primera és l'aigua. Un arbre ben establit necessita reg, i en un territori on l'aigua és escassa cal triar espècies adaptades al clima mediterrani i usar aigua regenerada. La segona és el manteniment: moltes plantacions fracassen, no per una mala elecció d'espècie, sinó perquè ningú no es fa càrrec de regar-les durant els tres primers anys. La tercera és l'espai: en molts carrers, l'arbrat entra en conflicte amb el cablatge, els aparcaments i les voreres estretes. I n'hi ha una quarta, que sol oblidar-se: els arbres creixen lentament, i els resultats no es veuen fins d'ací a quinze o vint anys. Esta paciència no encaixa amb els ritmes polítics."}, {"speaker": "Ponent", "voice": "lluc", "text": "Abans de passar als criteris, una precisió sobre la tria de les espècies, perquè ací se solen cometre errors de bona fe. No es tracta de plantar el que siga més vistós ni el que creix més de pressa, sinó el que millor s'adapta al lloc: arbres de fulla caduca on volem sol a l'hivern i ombra a l'estiu, espècies que toleren un sòl compactat i, sobretot, diversitat. Un carrer amb una sola espècie és molt vulnerable: una plaga pot deixar-lo sense ombra en un any. Per això, la regla que els recomane és que cap espècie supere el vint per cent de l'arbrat d'un barri."}, {"speaker": "Ponent", "voice": "lluc", "text": "Com avaluem l'èxit d'estes mesures? Proposaré tres criteris. El primer és mesurar: temperatures abans i després, amb sensors, i no només impressions. El segon, mirar qui se'n beneficia: si les actuacions es concentren en els barris que ja eren més agradables, haurem augmentat la desigualtat en lloc de reduir-la. I el tercer, comptar el cost total, inclosos el reg i el manteniment durant deu anys, i no només el de la plantació."}, {"speaker": "Ponent", "voice": "lluc", "text": "Per concloure: les ciutats poden refrescar-se si canviem la seua pell, amb més ombra, més cobertes verdes i patis escolars transformats. Però només ho aconseguirem si planifiquem l'aigua i el manteniment des del principi, i si mesurem i repartim els beneficis de manera justa. Moltes gràcies per l'atenció."}]}, "exercises": [{"q": "Eres tècnic o tècnica d'una empresa de jardineria i l'ajuntament d'un municipi mediterrani demana propostes per a refrescar els barris. Has assistit a esta conferència i t'adones que la informació et servix per a defendre un projecte. Escolta-la, pren apunts detallats i, a partir d'ells, redacta una proposta tècnica adreçada a la regidoria d'Urbanisme i Transició Ecològica: ha de justificar el projecte (illa de calor i equitat), plantejar actuacions prioritàries ben argumentades, preveure'n les limitacions (aigua, manteniment, espai, termini) i proposar criteris d'avaluació. No és un resum de la conferència: has de reelaborar la informació en un text de gènere diferent, amb finalitat persuasiva i en un registre formal administratiu, ordenat per apartats i sense citar el ponent.", "w": {"min_words": 350, "max_words": 400}}]}]},
  {"id": "ae3838f0-5a1d-525f-9e9c-be13ff3b105b", "category": "expressio_escrita", "type": "c2_ee_reelaboracio", "sort_order": 6, "title": "Reformular textos de referència", "name": "Nous lectors, funcions i registres: nota de premsa, text oral i guió divulgatiu a partir d'un text de referència", "content": "Reformula textos de referència per a elaborar-ne de nous, adequats, coherents i cohesionats, adaptats a lectors, funcions comunicatives, registres i contextos diferents (2.3).", "icon": "🔄", "color": "#B2EBF2", "blocks": [{"passage": {"media": "text", "title": "Resum executiu: la llengua en el comerç de proximitat", "lines": [{"text": "Estudi sobre els usos lingüístics en el comerç de proximitat d'una comarca valenciana (2024-2026). Resum executiu elaborat pel Grup de Recerca en Sociolingüística Aplicada."}, {"text": "Context. L'estudi s'emmarca en un programa de seguiment de l'ús social de la llengua i es va finançar amb una ajuda pública de recerca. Els tres municipis es van triar perquè representen tres situacions diferents: un nucli amb una presència alta del valencià, un altre en una situació de transició i un tercer amb una població molt diversa. Les dades es van recollir entre octubre de 2024 i maig de 2026."}, {"text": "1. Objectius. Esta investigació analitza els usos lingüístics en el comerç de proximitat de tres municipis de mida mitjana, amb la finalitat de descriure fins a quin punt la llengua d'atenció al públic respon a les preferències dels clients o a hàbits adquirits pels professionals, i d'identificar les barreres que dificulten l'ús del valencià en les interaccions comercials. Es parteix de la hipòtesi que la tria de llengua depén menys de la competència lingüística que de les expectatives que cada interlocutor atribuïx a l'altre."}, {"text": "2. Metodologia. Es van combinar tres tècniques: l'observació no participant de 480 interaccions en 96 establiments (carnisseries, fleques, farmàcies, botigues de roba i bars); una enquesta a 312 persones comerciants; i 24 entrevistes en profunditat. L'observació es va realitzar en franges horàries variades, sense que els observadors intervingueren en cap conversa, i es va registrar la llengua de salutació de cada interlocutor i si hi havia canvi de llengua durant la interacció."}, {"text": "3. Resultats de l'observació. Les dades mostren una realitat més matisada que la que suggerixen les percepcions generals. En el 58 % de les interaccions, qui atén i qui compra usen la mateixa llengua des de la salutació; en la resta, el 27 % presenta convergència cap al castellà i només el 15 % cap al valencià. La convergència cap al castellà és molt més freqüent quan la persona compradora és desconeguda (41 %) que quan és una clientela habitual (17 %), cosa que suggerix que la llengua de la salutació és, en bona part, una aposta basada en l'aparença i en la prudència: se suposa que l'interlocutor s'expressarà millor en castellà i s'evita el risc de fer-lo sentir incòmode."}, {"text": "4. Resultats de l'enquesta. Entre els comerciants enquestats, el 71 % declara que sap parlar valencià amb fluïdesa i el 64 % l'usa habitualment fora de la botiga, però només el 39 % el fa servir de manera sistemàtica en l'atenció al públic. El motiu que més citen (52 %) no és la dificultat per a expressar-se, sinó el desig de no incomodar el client; el segon (31 %) és la costum. Només el 9 % afirma haver rebut queixes per usar el valencià, i la major part d'estes queixes provenen de clients de pas, no de la clientela habitual."}, {"text": "5. Resultats de les entrevistes. Les entrevistes aporten el matís que les xifres no mostren. Diverses persones comerciants van descriure una mena de «cortesia lingüística invertida»: canviar al castellà per a ser amables, sense que ningú no ho haja demanat. Alguns clients, per la seua banda, van reconéixer que parlen en castellà als comerciants per la mateixa raó, cosa que genera un cercle de suposicions mútues. Els comerciants més joves van mostrar una actitud més favorable al valencià, però també una major inseguretat sobre la pròpia correcció, sobretot en la llengua escrita dels rètols i els cartells."}, {"text": "6. Conclusions. Les conclusions es poden resumir en tres punts. Primer, no hi ha una barrera de competència: la majoria dels professionals poden atendre en valencià. Segon, el canvi de llengua obeïx més a una norma de cortesia mal calibrada que a un rebuig del valencià. Tercer, les intervencions més eficaces no seran les campanyes genèriques de sensibilització, sinó les que treballen sobre eixes suposicions. En conseqüència, es recomana oferir als comerciants una formació breu i pràctica sobre estratègies per a mantindre la llengua; facilitar-los materials de suport (rètols, menús, vocabulari professional) revisats lingüísticament; i promoure iniciatives en què la clientela explicite que vol ser atesa en valencià, com ara distintius en les botigues."}, {"text": "7. Limitacions. Els resultats s'han de llegir amb cautela: l'estudi se circumscriu a tres municipis, no considera el comerç electrònic ni les grans superfícies, i la presència dels observadors, per discreta que fóra, podria haver influït en el comportament dels comerciants. Futures investigacions haurien d'ampliar la mostra i incorporar la perspectiva de les persones nouvingudes, que només han quedat representades de manera marginal en esta primera fase."}]}, "exercises": [{"q": "El grup de recerca vol difondre els resultats de l'estudi entre la ciutadania i et demana, com a responsable de comunicació d'una universitat, una nota de premsa per al diari comarcal. Reformula el resum executiu: converteix el registre acadèmic en un de periodístic i clar, comença amb un titular i una entrada que concentren la notícia (el resultat més sorprenent), organitza la informació per ordre d'interés i no segons l'estructura de l'informe, tria les dades més significatives sense saturar el lector de percentatges, explica la metodologia en una o dues frases i acaba amb les recomanacions. Pots atribuir les conclusions a l'equip investigador, però no t'inventes dades ni cites textuals.", "w": {"min_words": 250, "max_words": 300}}, {"q": "Una ràdio local convida el grup de recerca a explicar l'estudi en una intervenció de tres minuts dins d'un programa matinal, i tu has de preparar el guió que llegirà la investigadora. Reformula el contingut del resum com un text per a ser dit: usa un registre proper però cuidat, frases més curtes que en l'original, una obertura que capte l'atenció, repeticions i recapitulacions que ajuden a seguir-lo sense suport escrit, només les tres o quatre xifres imprescindibles (expressades de manera que s'entenguen a l'oïda) i un tancament que convide els oients a actuar. Evita els tecnicismes sense explicar i les construccions subordinades molt llargues.", "w": {"min_words": 250, "max_words": 300}}]}, {"passage": {"media": "text", "title": "Memòria tècnica: rehabilitació del Molí del Racó", "lines": [{"text": "Memòria tècnica del projecte de rehabilitació del Molí del Racó (extracte). Àrea de Patrimoni i Urbanisme de l'Ajuntament."}, {"text": "1. Antecedents. El Molí del Racó és un edifici de planta rectangular, de dos pisos i uns cent huitanta metres quadrats construïts, situat a la vora de la séquia major. Les primeres referències documentals són del segle XV, tot i que l'estructura actual correspon en gran part a una reforma del segle XVIII. Va funcionar com a molí fariner fins a la dècada de 1960 i, des d'aleshores, ha patit un abandonament progressiu que ha provocat l'ensorrament parcial de la coberta i la degradació de la maquinària."}, {"text": "Valor patrimonial. El molí conserva dos jocs de moles, l'eix de transmissió de fusta i un tram de la séquia de captació, cosa que el converteix en un dels exemples més complets d'arquitectura preindustrial de la comarca. Està protegit com a bé de rellevància local i forma part del recorregut patrimonial de la séquia major. Part del seu valor residix, a més, en el paisatge: l'entorn immediat conserva l'horta tradicional i un pont de pedra del segle XIX."}, {"text": "2. Estat de conservació. La inspecció prèvia ha revelat les patologies següents: a) pèrdua del 40 % de la coberta de teula àrab, amb la consegüent entrada d'aigua en el primer pis; b) humitats per capil·laritat en els murs de pedra de la planta baixa, que han degradat el morter de calç; c) corrosió i desajust de les moles i de l'eix de transmissió; d) esquerdes verticals en la façana orientada al nord, estabilitzades segons el seguiment fet durant sis mesos. No s'ha detectat cap patologia que comprometa la seguretat estructural del conjunt."}, {"text": "3. Criteris d'intervenció. El projecte se subjecta als criteris de mínima intervenció i de reversibilitat: es conservaran tots els elements originals que siga possible recuperar, se substituiran només els que estiguen irrecuperables i les parts noves es podran distingir amb claredat de les originals. Els materials seran compatibles amb els originals (morters de calç en lloc de ciment, fusta de pi per a les bigues i teula àrab recuperada), i s'evitarà qualsevol element que impedisca als murs evaporar la humitat."}, {"text": "4. Actuacions. S'executaran en tres fases. Fase 1 (sis mesos): consolidació estructural, reconstrucció de la coberta i drenatge perimetral per a evacuar l'aigua de pluja i frenar la humitat per capil·laritat. Fase 2 (huit mesos): restauració de la maquinària, amb el desmuntatge i la neteja de les moles, la reparació de l'eix i la recuperació del sistema hidràulic perquè puga funcionar de manera demostrativa. Fase 3 (quatre mesos): condicionament interior i accessibilitat, amb una rampa exterior, una passera interior de fusta i la instal·lació d'una il·luminació de baix consum."}, {"text": "5. Ús posterior. L'edifici es destinarà a centre d'interpretació de la cultura de l'aigua i de l'ofici de moliner, amb una exposició permanent al primer pis, un taller didàctic en la planta baixa i un espai polivalent per a activitats escolars. L'aforament màxim es fixa en vint-i-cinc persones simultànies, que és el que permet l'estructura i garantix la conservació dels elements. S'estima una afluència de quatre mil visitants anuals, un terç dels quals serà alumnat de centres educatius. Durant la redacció del projecte es va fer una consulta ciutadana en tres sessions, amb 140 participants; la majoria va demanar que l'edifici tinga un ús educatiu i que romanga obert almenys quatre dies per setmana."}, {"text": "6. Pressupost i termini. El pressupost d'execució per contracta és de 612.400 euros, IVA inclòs, i el termini total d'execució és de divuit mesos. El finançament es repartix entre l'ajuntament (45 %), la diputació (35 %) i una subvenció autonòmica (20 %). Una vegada finalitzades les obres, el manteniment anual s'estima en 28.000 euros, que assumirà l'Àrea de Patrimoni."}, {"text": "7. Riscos i mesures. Els principals riscos identificats són el desviament de costos per descobriments imprevistos durant la reconstrucció de la coberta, per a la qual cosa es reserva una partida del 8 %, i el risc d'inundació, atesa la proximitat de la séquia, que es mitiga amb la instal·lació de comportes de contenció i l'elevació dels equips elèctrics. La memòria completa, amb plànols i amidaments, es troba a disposició de qualsevol persona interessada en les oficines de l'Àrea, en horari d'atenció al públic i també en la seu electrònica de l'Ajuntament."}]}, "exercises": [{"q": "Quan acaben les obres, el molí rebrà visites de grups escolars de cinquè i sisè de primària, i el museu et demana el text de l'audioguia que escoltaran els xiquets, d'uns deu a dotze anys, mentre recorren l'edifici. Reformula la memòria tècnica com un text per a ser escoltat: dirigix-te directament als xiquets, convertix la informació tècnica en una història (el molí d'abans, com se'n va deteriorar i què s'ha fet perquè torne a viure), explica amb comparacions properes el funcionament de les moles i del reg de l'aigua, selecciona només les xifres que els poden interessar, usa preguntes i frases curtes perquè el text s'entenga a l'oïda i organitza'l en un recorregut per estances. Evita el llenguatge administratiu i no inventes dades que no figuren en l'original.", "w": {"min_words": 250, "max_words": 300}}]}]},
  {"id": "cdb843c9-2c3b-5d72-828f-0a67091f2c28", "category": "expressio_oral", "type": "c2_eo_divulgacio", "sort_order": 1, "title": "Presentar un tema complex a un públic profà", "name": "Explicar un tema complex a l'alumnat d'un institut, amb Neus", "content": "Presenta un tema complex davant d'un públic que no el coneix i adapta l'exposició a les seues necessitats: tria el nivell de detall, el lèxic i els exemples, i comprova que se't segueix (2.4).", "icon": "🔭", "color": "#D1C4E9", "metadata": {"character": "Neus, professora d'un institut que convida l'aprenent a fer una xarrada divulgativa", "voice": "gina", "initial_prompt": "Bon dia a tots! Xics, silenci, que tenim visita. Hui ens ve a parlar una persona que sap molt d'un tema que, ja ho advertisc, no té fama de ser fàcil. Vosté, que ho ha preparat, tria per on vol començar. I vosaltres, a escoltar i, si no enteneu res, a alçar la mà sense vergonya!", "prompt": "Ets Neus Ferrandis, professora de filosofia i coordinadora de projectes d'un institut de Gandia, de quaranta-set anys. Has convidat l'aprenent a fer una xarrada de divulgació de vint minuts a un públic mixt: una cinquantena d'alumnes de quart d'ESO i de batxillerat, alguns pares i mares i dos professors de ciències. Tractes l'aprenent de vosté, amb cordialitat i registre formal, i els alumnes també. L'aprenent ha d'explicar un tema complex a un públic que no el coneix. Si no en té cap de pensat, oferix-li'n tres: com funcionen els mercats financers i per què una crisi en un país afecta els altres; què és la bioètica i quins dilemes planteja l'edició genètica; o com es documenta i es recupera una llengua minoritzada. Deixa que òbriga la xarrada sense interrompre'l, però intervín per a fer de públic divers: un alumne de quart d'ESO que diu que no ha entés una paraula tècnica i que la vol explicada «com si tinguera dotze anys»; una alumna de batxillerat molt espavilada que fa una objecció conceptual precisa; una mare preocupada per la utilitat pràctica del tema; i un professor de ciències que matisa o corregix una simplificació. Fes que el públic reaccione a l'adaptació: si l'aprenent s'enreda en tecnicismes, diu que ningú no ha entés res; si es queda en un nivell infantil, un alumne protesta que «això ja ho sabem». Alça la mà de tant en tant per a demanar un exemple de la vida quotidiana, una analogia o una definició. Introduïx una pregunta inesperada fora del guió (per exemple, «i vosté, personalment, en què creu?») i un comentari irònic d'un alumne («Això és el que diu tothom i després no passa res»). Si l'aprenent se'n va per les branques, redirigix-lo amb tacte. Abans d'acabar, demana-li una síntesi de dos minuts adreçada a tothom i una pregunta de comprovació per als alumnes («Què us n'emporteu a casa?»). Acomiada'l amb fórmules d'agraïment formals.", "objectius": ["Introduïx el tema, delimita'l i anuncia'n l'estructura en un registre formal ben orientat a un públic mixt.", "Adapta el lèxic i el nivell de detall a l'audiència: defineix els termes tècnics necessaris i evita els que no calen.", "Usa analogies, exemples quotidians i imatges per a fer accessible allò que és abstracte, sense falsejar-ho.", "Respon amb precisió a les objeccions i a les preguntes inesperades del públic i reformula amb altres paraules quan no t'han entés.", "Comprova activament que se't segueix (preguntes de comprovació, resums parcials, ritme i pauses) i rectifica sobre la marxa.", "Tanca amb una síntesi clara dirigida a tot el públic i amb una conclusió que perdure."]}},
  {"id": "f054237c-6367-5353-bdc7-9b9ee8f40074", "category": "expressio_oral", "type": "c2_eo_espontani", "sort_order": 2, "title": "Interacció social espontània i col·loquial", "name": "Una vesprada de festa major a la plaça amb Vicent, un amic de tota la vida", "content": "Interactua de manera espontània, fluida i còmoda en una situació social, i usa amb precisió expressions idiomàtiques i col·loquials, ironies, al·lusions i canvis de to (2.4).", "icon": "🍻", "color": "#FFE0B2", "metadata": {"character": "Vicent, amic de l'aprenent, en la festa major del poble", "voice": "lluc", "initial_prompt": "Eeep, mira qui ha aparegut! Pensava que no et vindria de gust vindre, amb la setmana que portem. Vine, que la plaça està de gom a gom i la vesprada se m'ha anat de les mans. Conta'm, com va tot? I no em vingues amb el «bé, bé» de sempre, que et conec!", "prompt": "Ets Vicent Tormo, de quaranta-tres anys, paleta i animador incansable de la comissió de festes d'un poble de la Ribera. Ets amic de l'aprenent des de xicotet. Parles en registre col·loquial molt viu, amb molta gràcia i molta xerrameca: expressions idiomàtiques valencianes (tindre mà esquerra, de gom a gom, a tort i a dret, tocar el dos, fer i desfer), diminutius afectuosos, exclamacions i bromes. Tractes l'aprenent de tu. L'objectiu és una conversa espontània i distesa, sense guió: canvia de tema amb naturalitat i varia l'actitud perquè l'aprenent haja de seguir-te. Comença en to de broma i reprén la relació; passa després a comentar la festa i els enrenous de la comissió (les queixes dels veïns pels coets, el pressupost de l'orquestra, la paella del sopar); demana-li què ha fet últimament i reacciona amb interés, picardia o ironia. Introduïx expressions de sentit figurat que l'aprenent ha de captar pel context; si no les entén, no les expliques, però pots repetir-les d'una altra manera. Fes jocs de paraules i al·lusions compartides inventades (la vesprada que el seu cosí va caure a la séquia, el dia de la mascletà que es van quedar sense llum). Una vegada, fes una broma un poc pesada o ambigua perquè l'aprenent decidisca si la pren amb humor o te'n fa notar l'excés amb tacte. A mitja conversa, canvia de to: conta que el teu pare ha tingut un ensurt de salut i que estàs preocupat, perquè l'aprenent passe de l'humor a l'empatia sense estridències; després, recupera el to de festa. Canvia de tema sense avisar i torna a un tema anterior com si res. Cap al final, fes que s'acoste un veí gran a qui cal tractar de vosté, per a vore si l'aprenent canvia de registre amb naturalitat; després acomiada't amb una frase d'afecte i una dita o un refrany.", "objectius": ["Manté una conversa espontània i fluida, sense llargues pauses ni circumloquis, i segueix amb naturalitat els canvis de tema.", "Usa amb precisió expressions idiomàtiques i col·loquials valencianes, evitant els calcs del castellà, en el context adequat.", "Capta el sentit figurat, les ironies i les al·lusions de Vicent i hi respon amb humor i agilitat.", "Canvia de to amb naturalitat entre la broma i l'empatia quan la conversa es torna delicada.", "Respon amb tacte a una broma pesada o ambigua: l'accepta amb humor o la corregix amb elegància.", "Adapta el registre (tu/vosté) quan s'incorpora una persona gran, sense trencar la naturalitat."]}},
  {"id": "f17f13db-3e43-5f41-926a-641e0feb0ce4", "category": "expressio_oral", "type": "c2_eo_debat", "sort_order": 3, "title": "Debat formal i defensa d'una posició", "name": "Debat d'una associació cultural amb Gemma, l'advocada de la part contrària", "content": "Defén una posició amb arguments ben articulats i persuasius en un debat formal: respon a les objeccions, refuta els contraarguments, concedeix el que cal i manté el fil argumentatiu (2.4).", "icon": "⚖️", "color": "#CFD8DC", "metadata": {"character": "Gemma, advocada i membre de l'equip contrari en un debat formal", "voice": "gina", "initial_prompt": "Gràcies, senyor moderador. Si em permet, començaré jo la rèplica, perquè la intervenció d'obertura de la part contrària ha deixat sense respondre els tres punts que realment importen. Abans de res, però, voldria que quedara clar quina és la posició que defenem i quina la que combatem. Així doncs, tinc una pregunta per a vosté: quina és exactament la seua tesi?", "prompt": "Ets Gemma Soriano, advocada de quaranta-huit anys, membre de l'equip contrari en un debat formal organitzat per una associació cultural d'Alacant. La moció del debat és: «Les ciutats haurien de limitar l'accés dels turistes als centres històrics i fer-los pagar una taxa de visita». Si l'aprenent preferix un altre tema, adapta-t'hi: «L'ensenyament universitari hauria de ser gratuït» o «La jornada laboral s'ha de reduir a quatre dies sense reducció de sou». Pregunta-li primer quina posició defén (a favor o en contra) i ocupa tu l'oposada; mantín-la tota la conversa, encara que l'aprenent et convença en part. Tractes l'aprenent de vosté i parles en registre formal de debat, ben articulat, amb una ironia afilada però correcta. Fes objeccions de tipus diferents, una per torn: una dada contrària a la seua tesi (inventada però versemblant); una falàcia de què l'aprenent s'ha de defendre o que ha de detectar (la generalització apressada, l'argument d'autoritat, l'home de palla, la falsa dicotomia); una objecció de principi; un cas particular que semble contradir-lo; i una concessió estratègica («admetré que...») que després intentes tornar contra ell. Una vegada, tergiversa expressament un argument de l'aprenent perquè haja d'aclarir-lo i desmuntar la deformació. Si l'aprenent és vague, demana-li dades o un exemple. Si ho fa bé, reconeix-li el punt, però no cedisques tota la partida: matisa-ho i torna a la càrrega per un altre front. Interromp-lo una vegada amb un «permeta'm una puntualització» perquè haja de reconduir la intervenció amb elegància. Al final, demana a cada part una conclusió d'un minut: fes la teua i invita l'aprenent a fer la seua; acomiada't amb cortesia i reconeix-li la solidesa del discurs, si ho mereix.", "objectius": ["Formula una tesi clara i defén-la amb arguments ben jerarquitzats, amb dades i exemples, seguint un fil lògic fins a la conclusió.", "Respon a cada objecció amb precisió i serenitat: la refuta o en concedix la part vàlida sense abandonar la posició.", "Usa recursos persuasius (preguntes retòriques, repetició, èmfasi) i connectors argumentatius formals.", "Detecta i rebat les falàcies i les tergiversacions de la contrincant sense perdre la cortesia.", "Gestiona amb elegància les interrupcions i els canvis de rumb i recupera el torn de paraula.", "Tanca amb una conclusió breu i convincent que recapitule els arguments clau."]}},
  {"id": "15227f98-15de-52e9-9d43-c8c9f7abc228", "category": "expressio_oral", "type": "c2_eo_moderar", "sort_order": 4, "title": "Moderar una reunió o mediar en un conflicte", "name": "Mediar entre dos veïns pel tendal del terrat, amb Amadeu, el president de la comunitat", "content": "Conduïx amb autoritat una conversa estructurada: modera una reunió, dirigix una negociació o fa de mediador, ordena els torns, reformula, destensa i aconseguix un acord (2.4).", "icon": "🤝", "color": "#C8E6C9", "metadata": {"character": "Amadeu, president d'una comunitat de veïns, que alterna la seua veu amb la dels dos veïns enfrontats", "voice": "lluc", "initial_prompt": "Bé, jo crec que ja podem començar. Gràcies per haver vingut. Com sap, la comunitat l'ha designat mediador en el conflicte del terrat, perquè ens fiem de la seua imparcialitat. Jo sóc l'Amadeu, el president. Seguirem els torns que vosté diga, però l'avise: l'ambient està més calent del que sembla.", "prompt": "Ets Amadeu Cerdà, de seixanta anys, president d'una comunitat de veïns d'un edifici de València, i fas tres veus en esta conversa, marcant sempre clarament qui parla. La primera és la teua: ets conciliador, un poc cansat, i tractes l'aprenent de vosté, amb cordialitat formal. Les altres dos són les dels veïns enfrontats: Carme, que ha instal·lat al terrat un tendal i uns tests grans que els veïns de dalt consideren perillosos, i Enric, veí de l'àtic, brusc i colèric, que va denunciar l'obra i l'acusa de comportar-se «com si el terrat fóra seu». Tots dos han discutit a crits al replà. L'aprenent fa de mediador i moderador de la reunió: ha d'obrir-la, presentar-ne les normes, repartir els torns i buscar un acord. Perquè li siga difícil, fes que Enric interrompa i alce la veu; que Carme es posicione a la defensiva i li reprotxe un greuge antic (una gotera que mai no es va arreglar); que algú se'n vaja a un altre tema (la quota de l'ascensor); i que una de les parts faça una amenaça («aleshores anirem a un advocat»). Si el mediador no estructura la sessió, deixa que s'embolique; si ho fa bé, fes que cedisquen poc a poc. Introduïx un moment de tensió, un exabrupte, i un altre en què un dels veïns s'emociona o s'enfada molt. Si l'aprenent reformula i reconeix els sentiments, els veïns es calmen; si dona la raó a un, l'altre protesta per «parcialitat». Com a president, proposa una solució intermèdia poc realista perquè l'aprenent haja de matisar-la. Al final, exigix un acord concret (qui fa què i abans de quan) i demana que es resumisca per escrit; agraïx la feina i tanca la reunió.", "objectius": ["Obri la sessió amb autoritat: presenta'n els objectius, les normes de funcionament i la distribució dels torns.", "Ordena les intervencions i atura les interrupcions amb fermesa i cortesia, sense perdre la neutralitat.", "Reformula el que diu cada part, reconeix-ne els sentiments i extrau els interessos reals que hi ha darrere de les posicions.", "Destensa els moments d'agressivitat i reconduïx la conversa quan algú s'allunya del tema, amb mà esquerra.", "Proposa alternatives i fes avançar la negociació cap a un acord concret i equilibrat per a les dues parts.", "Tanca la reunió amb un resum dels acords (qui, què i quan) i confirma que tothom els accepta."]}},
  {"id": "0c29b763-10e8-576b-8025-4603fe1d4669", "category": "expressio_oral", "type": "c2_eo_discurs", "sort_order": 5, "title": "Discurs en un acte", "name": "Presentar un llibre en la biblioteca, amb Lluïsa, la bibliotecària", "content": "Pronuncia un parlament en un acte públic en registre formal: presenta un llibre o homenatja una persona amb un discurs estructurat, elegant, amb el to adequat i capaç de reaccionar als imprevistos (2.4).", "icon": "📖", "color": "#FFCCBC", "metadata": {"character": "Lluïsa, bibliotecària i presentadora d'un acte públic", "voice": "gina", "initial_prompt": "Bona vesprada i benvinguts a la biblioteca. Esta vesprada tenim el plaer de celebrar un acte molt especial. Abans de res, he de dir-los que el micròfon de l'última fila no acaba de funcionar i que la sala s'omplirà més del previst. Vosté, que és qui ens ha de parlar, quan vulga pot començar.", "prompt": "Ets Lluïsa Peris, bibliotecària de cinquanta-un anys i presentadora d'actes culturals en la biblioteca municipal d'un poble de la Safor. Tractes l'aprenent de vosté i parles en registre formal i càlid, amb fórmules protocol·làries. L'aprenent ha de pronunciar un discurs en un acte públic davant d'un públic nombrós (veïnat, familiars, l'alcaldessa i les autores). Si no té cap tema pensat, proposa-li'n un: presentar la novel·la d'una escriptora del poble, que acaba de publicar el seu primer llibre; fer el parlament d'homenatge a un mestre jubilat després de quaranta anys d'ensenyament; o pronunciar unes paraules en la celebració del cinquantè aniversari de la banda de música. Deixa que òbriga el discurs sense interrompre'l, i intervín només com a presentadora i com a públic: acompanya amb un «molt bé» discret, anuncia de tant en tant algun imprevist (el micròfon falla, algú obri la porta, un xiquet es posa a plorar) i observa com els gestiona. Quan ho escaiga, interromp breument per a presentar l'alcaldessa, que farà una salutació, perquè l'aprenent haja d'incorporar-la al discurs amb elegància. Si el discurs és massa pla, fes-li notar amb una pregunta («Podria dir-nos què té d'especial este llibre?») o demana-li una anècdota. Si és massa llarg, fes-li un senyal de temps. Després de la intervenció, fes de públic amb dos torns de preguntes: una d'una persona que expressa admiració però demana un detall concret, i una altra un poc incisiva, d'un lector crític («No li sembla que el final és massa previsible?»). Al final, agraïx-li el parlament amb una fórmula de cloenda, anuncia un refrigeri i tanca l'acte. Si ho fa especialment bé, comenta'n l'emoció.", "objectius": ["Obri el discurs amb una salutació protocol·lària adequada, adreça't al públic i a les autoritats i presenta el motiu de l'acte.", "Estructura el parlament amb un fil clar (introducció, desenrotllament, tancament) i mantín un registre formal i elegant.", "Usa recursos retòrics i expressius (anècdotes, imatges, cites, paral·lelismes) sense caure en la grandiloqüència.", "Adapta el to a l'ocasió (emotiu, humorístic o solemne) i cuida l'èmfasi, les pauses i l'entonació.", "Reacciona amb naturalitat als imprevistos (fallada del micròfon, interrupcions, presentació d'una autoritat) sense perdre el fil.", "Respon amb cortesia i seguretat a les preguntes posteriors, inclosa una crítica, i tanca amb fórmules d'agraïment."]}},
  {"id": "75091b72-4584-5d9c-b163-0cf1021dd137", "category": "expressio_oral", "type": "c2_eo_registres", "sort_order": 6, "title": "Adaptació de registre a interlocutors diversos", "name": "Explicar la mateixa notícia a tres persones diferents, amb Marc", "content": "Explica el mateix a interlocutors molt diferents dins de la mateixa conversa i adapta el registre, el lèxic, el nivell de detall i el to a cada un, sense perdre el fil (2.4).", "icon": "🎭", "color": "#B2DFDB", "metadata": {"character": "Marc, amic de l'aprenent, que fa diferents papers dins d'una mateixa conversa", "voice": "lluc", "initial_prompt": "Hola! Tinc un problema i et necessite com a intermediari. La residència on viu la meua iaia ha canviat les condicions del contracte i ho he d'explicar hui a tres persones ben diferents. Jo faré de mi mateix i, després faré també de les altres. Tu has de fer d'intermediari. Vinga, comencem?", "prompt": "Ets Marc Ribes, de trenta-nou anys, amic de l'aprenent, i en esta conversa interpretes també diversos personatges de l'entorn. La situació és que la residència on viu la iaia de Marc, l'àvia Rosa, ha modificat les condicions del contracte: ha pujat la quota un quinze per cent i ha reduït les hores de fisioteràpia. L'aprenent ha d'explicar la mateixa situació a interlocutors molt diferents que interpretes tu, marcant sempre qui parla i canviant de to, de lèxic i de nivell d'estudis. Comença com a tu mateix, en registre col·loquial (tractes l'aprenent de tu), i demana-li com explicaria el cas als altres. Després fes tres papers, alternant-los: 1) La iaia Rosa, de huitanta-set anys, un poc sorda i amb pocs estudis, que no entén tecnicismes, s'espanta amb facilitat i parla en un valencià molt tradicional i col·loquial; l'aprenent ha de tranquil·litzar-la i explicar-li-ho amb paraules senzilles, sense condescendència. 2) Dolors, assessora jurídica d'una associació de consumidors, de cinquanta anys, que tracta l'aprenent de vosté i parla en registre tècnic i formal; vol dades exactes (dates, clàusules, imports, organisme competent) i demana que l'aprenent s'expresse amb precisió. 3) Nil, el cosí de setze anys, que s'ho pren tot amb ironia, parla en un registre molt jove i informal i vol saber «de què va tot això» en dues frases. Fes els canvis de manera abrupta (per exemple, la iaia s'incorpora a la conversa en mig de l'explicació a Dolors) perquè l'aprenent haja de reajustar el registre a l'instant. Introduïx malentesos (la iaia pensa que la volen traure de la residència; Nil creu que és una estafa), preguntes inesperades i canvis de to (de la preocupació a la indignació, de la tendresa a la ironia). Si l'aprenent usa el mateix registre amb dos interlocutors o s'equivoca de tractament (tu/vosté), reacciona dins del personatge amb naturalitat (confusió, sorpresa). Al final, torna a ser Marc i demana-li què ha canviat en cada explicació i per què.", "objectius": ["Explica la mateixa informació de manera adequada a cada interlocutor (la iaia, l'assessora, el cosí), triant el lèxic, el nivell de detall i els exemples més convenients.", "Usa el registre i el tractament (tu/vosté) correctes per a cada persona i mantín-los de manera coherent mentre dure cada intervenció.", "Canvia de registre a l'instant quan canvia l'interlocutor, sense arrossegar les formes del personatge anterior.", "Tradueix els tecnicismes a un llenguatge planer per a la iaia i usa una terminologia precisa amb l'assessora.", "Detecta i desfà els malentesos de cada interlocutor sense perdre la calma ni la cortesia.", "Reflexiona al final sobre com ha adaptat el to i el contingut i justifica les decisions."]}}
  ]$data$;
  pautes text := E'\n\n' ||
    'Pautes: l''aprenent prepara el nivell C2 (usuari experimentat avançat) de la JQCV i practica l''expressió i interacció orals. Parla en valencià general (normativa de l''AVL), amb el registre que demana la situació (formal quan toca), de manera fluida, espontània i natural, amb un vocabulari ric, precís i idiomàtic: usa connectors variats, estructures complexes, frases fetes i, si la situació ho permet, al·lusions, humor o ironia. ' ||
    'Fes torns breus (màxim 3-4 frases) amb una o dues preguntes per torn. Exigix-li un nivell C2: demana-li que argumente, matise, reformule, done exemples, resumisca o aclarisca; planteja-li objeccions, preguntes inesperades i, de tant en tant, alguna ambigüitat perquè haja de demanar aclariments. Si respon amb frases curtes o estereotipades, repregunta perquè desenvolupe les idees. ' ||
    'Mai no ixes del personatge ni fas lliçons de gramàtica: si l''aprenent s''equivoca o usa un castellanisme, reformula la frase correcta dins de la teua resposta amb naturalitat. ' ||
    E'\nObjectius que ha de complir l''aprenent (guia la conversa perquè els complisca d''un en un, sense enumerar-los): ';
  r jsonb;
  b jsonb;
  e jsonb;
  m jsonb;
  rid uuid;
  pid uuid;
  ppos smallint;
  epos smallint;
BEGIN
  FOR r IN SELECT * FROM jsonb_array_elements(catalog) LOOP
    rid := (r->>'id')::uuid;
    -- Xats: el system_prompt és el del personatge, les pautes del C2 i els objectius.
    m := coalesce(r->'metadata', '{}');
    IF m ? 'prompt' THEN
      m := (m - 'prompt') || jsonb_build_object('system_prompt',
        (m->>'prompt') || pautes ||
        (SELECT string_agg(o, ' | ') FROM jsonb_array_elements_text(m->'objectius') AS o) ||
        ' Quan els haja complit tots, tanca la conversa amb naturalitat i acomiada''t.');
    END IF;

    INSERT INTO public.resources (id, name, type, category, content, difficulty, xp_earned, sort_order, metadata)
    VALUES (
      rid, r->>'name', r->>'type', r->>'category', r->>'content', 'C2', 15, (r->>'sort_order')::smallint,
      jsonb_build_object('icon', r->>'icon', 'color', r->>'color', 'section_name', r->>'title') || m
    )
    ON CONFLICT (id) DO UPDATE SET
      name = EXCLUDED.name,
      type = EXCLUDED.type,
      category = EXCLUDED.category,
      content = EXCLUDED.content,
      difficulty = EXCLUDED.difficulty,
      xp_earned = EXCLUDED.xp_earned,
      sort_order = EXCLUDED.sort_order,
      -- Conserva la lliçó fixa («Aprendre lliçó»), si una migració posterior n'hi afig.
      metadata = EXCLUDED.metadata || jsonb_strip_nulls(jsonb_build_object('lesson', resources.metadata -> 'lesson'));

    DELETE FROM public.practice_exercises WHERE resource_id = rid AND level = 'C2';
    DELETE FROM public.practice_passages WHERE resource_id = rid AND level = 'C2';

    ppos := 0;
    epos := 0;
    FOR b IN SELECT * FROM jsonb_array_elements(
      coalesce(r->'blocks', CASE WHEN r ? 'exercises' THEN jsonb_build_array(jsonb_build_object('exercises', r->'exercises')) ELSE '[]' END)
    ) LOOP
      pid := NULL;
      IF b ? 'passage' THEN
        ppos := ppos + 1;
        INSERT INTO public.practice_passages (resource_id, level, position, media, title, lines, audio_url)
        VALUES (
          rid, 'C2', ppos, b->'passage'->>'media', b->'passage'->>'title', b->'passage'->'lines',
          CASE WHEN b->'passage'->>'media' = 'audio' THEN format('/audio/practice/%s-c2-%s.wav', r->>'type', ppos) END
        )
        RETURNING id INTO pid;
      END IF;

      FOR e IN SELECT * FROM jsonb_array_elements(b->'exercises') LOOP
        epos := epos + 1;
        INSERT INTO public.practice_exercises (resource_id, level, position, passage_id, kind, prompt, options, answers, task, explanation)
        VALUES (
          rid, 'C2', epos, pid,
          CASE WHEN e ? 'o' THEN 'choice' WHEN e ? 'a' THEN 'fill' WHEN e ? 'w' THEN 'writing' ELSE 'form' END,
          e->>'q',
          CASE WHEN e ? 'o' THEN ARRAY(SELECT jsonb_array_elements_text(e->'o')) END,
          CASE WHEN e ? 'o' THEN ARRAY[e->'o'->>0] WHEN e ? 'a' THEN ARRAY(SELECT jsonb_array_elements_text(e->'a')) END,
          CASE WHEN e ? 'w' THEN e->'w' WHEN e ? 'f' THEN jsonb_build_object('fields', e->'f') END,
          e->>'e'
        );
      END LOOP;
    END LOOP;
  END LOOP;
END
$do$;
